class ChatGPTBrowserClient:
    def __init__(self, config: ChatGPTBrowserConfig):
        self.config = config
        self._artifact_dir = Path(self.config.debug_artifact_dir)
        self._profile_key = str(Path(self.config.profile_dir).expanduser().resolve())
        self._rate_limit_cooldown_path = Path(self._profile_key) / '.conversation_history_rate_limit_until'
        self._rate_limit_events: list[dict[str, object]] = []
        self._rate_limit_cooldown_wait_seconds_total = 0.0
        self._rate_limit_cooldown_wait_count = 0
        self._navigation_noop_skip_count = 0
        self._conversation_history_fetch_attempt_count = 0
        self._conversation_history_fetch_skipped_count = 0
        self._conversation_history_cooldown_skip_count = 0
        self._conversation_history_request_shielded_count = 0
        self._conversation_history_request_shield_allowed_count = 0
        self._conversation_history_request_shield_events: list[dict[str, object]] = []
        self._conversation_history_explicit_fetch_depth = 0
        self._google_device_prompt_logged_keys: set[str] = set()
        self._browser_action_events: list[dict[str, object]] = []
        if self.config.debug:
            self._artifact_dir.mkdir(parents=True, exist_ok=True)


    def _record_browser_action(
        self,
        *,
        kind: str,
        label: str,
        strategy: str | None = None,
        status: str | None = None,
        cooldown_sensitive: bool = True,
        **fields: Any,
    ) -> None:
        event: dict[str, object] = {
            'kind': kind,
            'label': label,
            'monotonic_time': round(time.monotonic(), 6),
            'cooldown_sensitive': bool(cooldown_sensitive),
        }
        if strategy is not None:
            event['strategy'] = strategy
        if status is not None:
            event['status'] = status
        for key, value in fields.items():
            if value is None:
                continue
            if isinstance(value, (str, int, float, bool)):
                event[key] = value
            else:
                event[key] = self._safe_repr(value)
        self._browser_action_events.append(event)
        if len(self._browser_action_events) > 500:
            del self._browser_action_events[: len(self._browser_action_events) - 500]

    def _browser_action_audit_snapshot(self) -> dict[str, object]:
        events = list(self._browser_action_events)
        click_attempts = [event for event in events if str(event.get('kind')) == 'click_attempt']
        click_successes = [event for event in events if str(event.get('kind')) == 'click_success']
        fallback_clicks = [
            event
            for event in click_attempts
            if str(event.get('strategy') or 'primary') not in {'primary', 'skip'}
        ]
        label_counts: dict[str, int] = {}
        for event in click_attempts:
            label = str(event.get('label') or '')
            label_counts[label] = label_counts.get(label, 0) + 1
        repeated = [
            {'label': label, 'attempt_count': count}
            for label, count in sorted(label_counts.items())
            if count > 1
        ]
        cooldown_risk_score = len(click_attempts) + (2 * len(fallback_clicks)) + (3 * len(repeated))
        shortest_path_status = 'review' if fallback_clicks or repeated else 'minimal_observed'
        recommendation = (
            'Review repeated/fallback clicks before broad live validation; each extra click increases cooldown/429 exposure.'
            if shortest_path_status == 'review'
            else 'No repeated or fallback click attempts were observed in this operation.'
        )
        return {
            'schema': 'promptbranch.browser_action_audit',
            'schema_version': '1.0',
            'event_count': len(events),
            'click_attempt_count': len(click_attempts),
            'click_success_count': len(click_successes),
            'fallback_click_count': len(fallback_clicks),
            'repeated_click_labels': repeated,
            'shortest_path_status': shortest_path_status,
            'cooldown_risk_score': cooldown_risk_score,
            'recommendation': recommendation,
            'events': events[-200:],
        }

    def _attach_browser_action_audit(self, result: Any) -> Any:
        if isinstance(result, dict):
            result.setdefault('browser_action_audit', self._browser_action_audit_snapshot())
        return result

    def _record_ask_progress(self, **fields: Any) -> None:
        try:
            _LATEST_ASK_PROGRESS.update({
                "updated_at_monotonic": time.monotonic(),
                "profile_dir": str(self.config.profile_dir),
                **fields,
            })
        except Exception:
            pass

    def _clear_ask_progress(self) -> None:
        try:
            clear_latest_ask_progress()
        except Exception:
            pass

    def _is_conversation_history_url(self, url: str) -> bool:
        normalized = (url or '').lower()
        return any(fragment in normalized for fragment in CONVERSATION_HISTORY_RATE_LIMIT_PATH_FRAGMENTS)

    def _is_global_conversation_history_url(self, url: str) -> bool:
        try:
            parsed = urlparse(url or '')
        except Exception:
            return False
        return (parsed.path or '').lower().rstrip('/') == '/backend-api/conversations'

    def _conversation_history_request_shield_enabled(self) -> bool:
        mode = str(getattr(self.config, 'conversation_history_request_shield_mode', 'fulfill_empty') or 'fulfill_empty').strip().lower()
        return mode not in {'', 'disabled', 'off', 'false', '0', 'allow'}

    def _record_conversation_history_request_shield_event(
        self,
        *,
        kind: str,
        url: str,
        operation_name: str | None = None,
        reason: str | None = None,
    ) -> None:
        event: dict[str, object] = {
            'kind': kind,
            'url': self._redact_backend_api_url(url).get('redacted_url', str(url or '')[:200]),
            'operation_name': operation_name or '',
            'monotonic_time': round(time.monotonic(), 6),
        }
        if reason:
            event['reason'] = reason
        if kind == 'conversation_history_request_shielded':
            self._conversation_history_request_shielded_count += 1
        elif kind == 'conversation_history_request_allowed_explicit_fetch':
            self._conversation_history_request_shield_allowed_count += 1
        self._conversation_history_request_shield_events.append(event)
        if len(self._conversation_history_request_shield_events) > 200:
            del self._conversation_history_request_shield_events[: len(self._conversation_history_request_shield_events) - 200]

    async def _conversation_history_request_shield_route(self, route: Any, request: Any, *, operation_name: str = '') -> None:
        url = str(getattr(request, 'url', '') or '')
        method = str(getattr(request, 'method', 'GET') or 'GET').upper()
        if not self._conversation_history_request_shield_enabled() or method != 'GET' or not self._is_global_conversation_history_url(url):
            await route.continue_()
            return
        if self._conversation_history_explicit_fetch_depth > 0:
            self._record_conversation_history_request_shield_event(
                kind='conversation_history_request_allowed_explicit_fetch',
                url=url,
                operation_name=operation_name,
                reason='explicit_promptbranch_history_fetch',
            )
            await route.continue_()
            return
        payload = {
            'items': [],
            'conversations': [],
            'total': 0,
            'has_more': False,
            'promptbranch_request_shield': True,
        }
        self._record_conversation_history_request_shield_event(
            kind='conversation_history_request_shielded',
            url=url,
            operation_name=operation_name,
            reason='global_conversation_history_auto_request',
        )
        await route.fulfill(
            status=200,
            content_type='application/json',
            body=json.dumps(payload),
            headers={
                'cache-control': 'no-store',
                'x-promptbranch-conversation-history-shield': 'fulfill_empty',
            },
        )

    async def _install_conversation_history_request_shield(self, context: Any, *, operation_name: str) -> None:
        if not self._conversation_history_request_shield_enabled():
            self._log('rate-limit', 'conversation-history request shield disabled', operation=operation_name)
            return
        async def handle_conversation_history_route(route: Any, request: Any) -> None:
            await self._conversation_history_request_shield_route(route, request, operation_name=operation_name)

        try:
            await context.route(
                '**/backend-api/conversations**',
                handle_conversation_history_route,
            )
            self._log(
                'rate-limit',
                'conversation-history request shield installed',
                operation=operation_name,
                mode=getattr(self.config, 'conversation_history_request_shield_mode', 'fulfill_empty'),
            )
        except Exception as exc:
            self._log('rate-limit', 'conversation-history request shield install failed', operation=operation_name, error=repr(exc))

    def _is_backend_api_url(self, url: str) -> bool:
        normalized = (url or '').lower()
        return '/backend-api/' in normalized or normalized.startswith('wss://chatgpt.com/backend-api/')

    def _redact_backend_api_url(self, url: str) -> dict[str, Any]:
        text = str(url or '')
        try:
            parsed = urlparse(text)
        except Exception:
            return {'path': text[:200], 'query_keys': [], 'redacted_url': text[:200]}
        query_keys = sorted({key for key, _value in parse_qsl(parsed.query or '', keep_blank_values=True)})
        redacted_query = '&'.join(f'{key}=<redacted>' for key in query_keys)
        scheme = parsed.scheme or 'https'
        netloc = parsed.netloc or 'chatgpt.com'
        redacted_url = urlunparse((scheme, netloc, parsed.path, '', redacted_query, ''))
        return {
            'path': parsed.path or text[:200],
            'query_keys': query_keys,
            'redacted_url': redacted_url,
        }

    def _parse_retry_after_seconds(self, value: object) -> float | None:
        text = str(value or '').strip()
        if not text:
            return None
        try:
            return max(0.0, float(text))
        except ValueError:
            pass
        try:
            # HTTP-date retry-after values are uncommon here but cheap to parse
            # enough for diagnostics. Avoid importing email.utils globally.
            from email.utils import parsedate_to_datetime

            dt = parsedate_to_datetime(text)
            return max(0.0, dt.timestamp() - time.time())
        except Exception:
            return None

    def _backend_api_surfaces_snapshot(self) -> list[dict[str, Any]]:
        return [dict(item) for item in CHATGPT_BACKEND_API_SURFACES]

    def _rate_limit_cooldown_snapshot(self) -> dict[str, Any]:
        cooldown_until = self._read_rate_limit_cooldown_until()
        remaining = max(0.0, cooldown_until - time.time())
        return {
            'path': str(self._rate_limit_cooldown_path),
            'active': remaining > 0,
            'cooldown_until_unix': cooldown_until if cooldown_until > 0 else None,
            'cooldown_remaining_seconds': round(remaining, 3),
        }

    def _read_rate_limit_cooldown_until(self) -> float:
        try:
            raw = self._rate_limit_cooldown_path.read_text(encoding='utf-8').strip()
            return float(raw) if raw else 0.0
        except FileNotFoundError:
            return 0.0
        except Exception as exc:
            self._log('rate-limit', 'failed reading cooldown file', path=str(self._rate_limit_cooldown_path), error=str(exc))
            return 0.0

    def _conversation_history_cooldown_remaining(self) -> float:
        return max(0.0, self._read_rate_limit_cooldown_until() - time.time())

    def _conversation_history_cooldown_active(self) -> bool:
        return self._conversation_history_cooldown_remaining() > 0

    def _normalize_navigation_url(self, url: str) -> str:
        try:
            parsed = urlparse(url or '')
        except Exception:
            return (url or '').strip()
        path = (parsed.path or '/').rstrip('/') or '/'
        query = urlencode(sorted(parse_qsl(parsed.query, keep_blank_values=True)))
        return urlunparse((parsed.scheme.lower(), parsed.netloc.lower(), path, '', query, ''))

    def _navigation_requires_refresh(self, *, label: str, current_url: str, target_url: str) -> bool:
        normalized_label = (label or '').lower()
        if 'refresh' in normalized_label:
            return True
        if 'reload' in normalized_label:
            return True
        if normalized_label == "chat-home-after-login" and self._is_conversation_url(target_url):
            hydration_mode = (os.getenv("CHATGPT_HYDRATION_MODE") or "").strip().lower()
            if hydration_mode in {"legacy", "strict", "full", "reload", "force_reload"}:
                return True
            # v0.0.278.16: do not force a same-conversation reload by default.
            # The warm-task hydration gate below verifies same URL + usable
            # composer before skipping transcript-turn hydration. If the page is
            # not warm/usable it falls back to the older fail-closed transcript
            # hydration path.
            return False
        return False

    def _warm_task_hydration_reuse_enabled(self) -> bool:
        mode = (os.getenv("CHATGPT_HYDRATION_MODE") or "auto").strip().lower()
        if mode in {"legacy", "strict", "full", "reload", "force_reload", "off", "disabled", "false", "0", "no"}:
            return False
        if (os.getenv("CHATGPT_DEEP_DEBUG") or "").strip().lower() in {"1", "true", "yes"}:
            return mode in {"warm", "warm_task_reuse", "reuse", "auto_warm"}
        return True

    def _record_conversation_history_skip(self, *, reason: str, label: str | None = None, url: str | None = None) -> None:
        self._conversation_history_fetch_skipped_count += 1
        if reason == 'cooldown_active':
            self._conversation_history_cooldown_skip_count += 1
        self._record_rate_limit_event(kind='conversation_history_skipped', trigger='skip', url=url, label=label, wait_seconds=self._conversation_history_cooldown_remaining())
        self._log('rate-limit', 'skipping conversation-history fetch', reason=reason, label=label, url=url, cooldown_remaining=round(self._conversation_history_cooldown_remaining(), 3))

    def _write_rate_limit_cooldown_until(self, cooldown_until: float) -> None:
        try:
            self._rate_limit_cooldown_path.parent.mkdir(parents=True, exist_ok=True)
            self._rate_limit_cooldown_path.write_text(f'{cooldown_until:.6f}', encoding='utf-8')
        except Exception as exc:
            self._log('rate-limit', 'failed writing cooldown file', path=str(self._rate_limit_cooldown_path), error=str(exc))

    def _record_rate_limit_event(self, *, kind: str, trigger: str | None = None, status: int | None = None, url: str | None = None, label: str | None = None, wait_seconds: float | None = None) -> None:
        event: dict[str, object] = {
            'kind': kind,
            'monotonic_time': round(time.monotonic(), 6),
        }
        if trigger is not None:
            event['trigger'] = trigger
        if status is not None:
            event['status'] = status
        if url:
            event['url'] = url
        if label:
            event['label'] = label
        if wait_seconds is not None:
            event['wait_seconds'] = round(max(0.0, float(wait_seconds)), 3)
        self._rate_limit_events.append(event)

    def _rate_limit_telemetry_snapshot(self) -> dict[str, object]:
        events = list(self._rate_limit_events)
        return {
            'rate_limit_modal_detected': any(event.get('kind') == 'modal_detected' for event in events),
            'conversation_history_429_seen': any(int(event.get('status') or 0) == 429 for event in events),
            'backend_api_guardrail_seen': any(event.get('kind') == 'backend_api_guardrail' for event in events),
            'cooldown_wait_seconds_total': round(self._rate_limit_cooldown_wait_seconds_total, 3),
            'cooldown_wait_count': int(self._rate_limit_cooldown_wait_count),
            'conversation_history_fetch_attempt_count': int(self._conversation_history_fetch_attempt_count),
            'conversation_history_fetch_skipped_count': int(self._conversation_history_fetch_skipped_count),
            'conversation_history_cooldown_skip_count': int(self._conversation_history_cooldown_skip_count),
            'conversation_history_request_shield_enabled': self._conversation_history_request_shield_enabled(),
            'conversation_history_request_shield_mode': str(getattr(self.config, 'conversation_history_request_shield_mode', 'fulfill_empty')),
            'conversation_history_request_shielded_count': int(self._conversation_history_request_shielded_count),
            'conversation_history_request_shield_allowed_count': int(self._conversation_history_request_shield_allowed_count),
            'conversation_history_request_shield_events': list(self._conversation_history_request_shield_events[-50:]),
            'navigation_noop_skip_count': int(self._navigation_noop_skip_count),
            'service_rate_limit_events': events,
        }

    def _attach_rate_limit_telemetry(self, result: Any) -> Any:
        telemetry = self._rate_limit_telemetry_snapshot()
        if isinstance(result, dict):
            result.setdefault('rate_limit_telemetry', telemetry)
        return self._attach_browser_action_audit(result)

    def _note_conversation_history_rate_limit(self, *, trigger: str, url: str, status: int | None = None) -> None:
        cooldown_seconds = max(0.0, float(self.config.conversation_history_rate_limit_cooldown_seconds))
        self._record_rate_limit_event(kind='conversation_history_rate_limit', trigger=trigger, status=status, url=url)
        if cooldown_seconds <= 0:
            return
        cooldown_until = time.time() + cooldown_seconds
        existing = self._read_rate_limit_cooldown_until()
        if existing > cooldown_until:
            cooldown_until = existing
        self._write_rate_limit_cooldown_until(cooldown_until)
        self._log(
            'rate-limit',
            'conversation history rate limit noted',
            trigger=trigger,
            status=status,
            url=url,
            cooldown_seconds=cooldown_seconds,
            cooldown_until=cooldown_until,
        )

    def _browser_challenge_type_for_guardrail(self) -> str:
        """Return the structured challenge status for the active browser profile.

        ChatGPT /backend-api endpoints are private web-app internals.  Promptbranch
        must not treat them as an operational API contract; observed 403 responses
        are diagnostic evidence that the current browser/profile is challenged or
        forbidden.  The returned value identifies which profile surface should be
        re-bootstrapped by the operator.
        """

        profile = str(getattr(self.config, "profile_dir", "") or "").replace("\\", "/").lower()
        if ".pb_profile_local_debug_pools" in profile or "release-live/slots" in profile:
            return "docker_live_profile_challenged"
        if ".pb_profile/browser/default" in profile or profile.endswith("/app/profile") or profile.endswith("/profile"):
            return "docker_standard_profile_challenged"
        return "browser_backend_403_guardrail"

    def _note_backend_api_guardrail(
        self,
        *,
        trigger: str,
        url: str,
        status: int | None = None,
        retry_after_seconds: float | None = None,
    ) -> None:
        self._record_rate_limit_event(kind='backend_api_guardrail', trigger=trigger, status=status, url=url, wait_seconds=retry_after_seconds)
        if bool(getattr(self.config, "fail_fast_on_challenge", False)) and int(status or 0) == 403:
            challenge_type = self._browser_challenge_type_for_guardrail()
            self._log(
                'rate-limit',
                'backend-api 403 treated as browser challenge guardrail; skipping persisted cooldown',
                trigger=trigger,
                status=status,
                url=url,
                cooldown_skipped=True,
                challenge_type=challenge_type,
                backend_api_guardrail_terminal=True,
            )
            return
        cooldown_seconds = retry_after_seconds
        if cooldown_seconds is None:
            cooldown_seconds = max(0.0, float(self.config.conversation_history_rate_limit_cooldown_seconds))
        cooldown_seconds = max(0.0, float(cooldown_seconds))
        if cooldown_seconds <= 0:
            return
        cooldown_until = time.time() + cooldown_seconds
        existing = self._read_rate_limit_cooldown_until()
        if existing > cooldown_until:
            cooldown_until = existing
        self._write_rate_limit_cooldown_until(cooldown_until)
        self._log(
            'rate-limit',
            'backend-api guardrail noted',
            trigger=trigger,
            status=status,
            url=url,
            cooldown_seconds=cooldown_seconds,
            cooldown_until=cooldown_until,
        )

    async def _respect_context_spacing(self) -> None:
        spacing = max(0.0, float(self.config.min_context_spacing_seconds))
        if spacing <= 0:
            return
        last_closed_at = _PROFILE_LAST_CONTEXT_CLOSED_AT.get(self._profile_key)
        if last_closed_at is None:
            return
        wait_seconds = (last_closed_at + spacing) - time.monotonic()
        if wait_seconds <= 0:
            return
        self._log('rate-limit', 'waiting before launching next browser context', wait_seconds=round(wait_seconds, 3), profile_dir=self._profile_key)
        await asyncio.sleep(wait_seconds)

    async def _respect_rate_limit_cooldown(self) -> None:
        cooldown_until = self._read_rate_limit_cooldown_until()
        remaining = cooldown_until - time.time()
        if remaining <= 0:
            return
        wait_seconds = max(0.0, float(remaining))
        self._rate_limit_cooldown_wait_seconds_total += wait_seconds
        self._rate_limit_cooldown_wait_count += 1
        self._record_rate_limit_event(kind='cooldown_wait', wait_seconds=wait_seconds, url=str(self._rate_limit_cooldown_path))
        self._log('rate-limit', 'waiting for persisted conversation history cooldown', wait_seconds=round(wait_seconds, 3), path=str(self._rate_limit_cooldown_path))
        await asyncio.sleep(wait_seconds)

    async def _wait_after_rate_limit_modal_ack(self, *, label: str) -> None:
        wait_seconds = max(0.0, float(getattr(self.config, 'rate_limit_modal_ack_wait_seconds', 60.0)))
        if wait_seconds <= 0:
            return
        self._rate_limit_cooldown_wait_seconds_total += wait_seconds
        self._rate_limit_cooldown_wait_count += 1
        self._record_rate_limit_event(kind='modal_ack_wait', trigger='modal_ack', label=label, wait_seconds=wait_seconds)
        self._log('rate-limit', 'waiting after rate limit modal acknowledgement', label=label, wait_seconds=round(wait_seconds, 3))
        await asyncio.sleep(wait_seconds)
        self._write_rate_limit_cooldown_until(time.time())
        self._record_rate_limit_event(kind='modal_ack_wait_satisfied_cooldown', trigger='modal_ack', label=label, wait_seconds=0.0)
        self._log('rate-limit', 'rate limit modal acknowledgement wait completed', label=label)

    def _can_wait_for_keep_open(self) -> bool:
        stdin = getattr(sys, "stdin", None)
        if stdin is None:
            return False
        is_tty = getattr(stdin, "isatty", None)
        if not callable(is_tty):
            return False
        try:
            return bool(is_tty())
        except Exception as exc:
            self._log('debug', 'stdin tty check failed during keep-open evaluation', error=repr(exc))
            return False

    async def _pause_for_keep_open(self, prompt: str) -> None:
        if not self._can_wait_for_keep_open():
            self._log('debug', 'skipping keep-open wait because stdin is not interactive', prompt=prompt)
            return
        try:
            await asyncio.to_thread(input, prompt)
        except EOFError:
            self._log('debug', 'skipping keep-open wait after stdin EOF', prompt=prompt)

    def _auth_readiness_session_key(self) -> str:
        return f"{self._profile_key}|{self.config.project_url}|{self.driver_name}|{self.config.browser_channel or 'default'}"

    def _auth_readiness_keep_open_seconds(self) -> float:
        raw = os.getenv("PROMPTBRANCH_AUTH_READINESS_KEEP_OPEN_SECONDS", "300")
        try:
            return max(1.0, float(raw))
        except (TypeError, ValueError):
            return 300.0

    def _auth_readiness_status_from_state(self, state: dict[str, Any]) -> str:
        challenge_detected = bool(state.get("challenge_detected"))
        logged_in = bool(state.get("logged_in"))
        if challenge_detected:
            return "auth_challenge_detected"
        if logged_in:
            return "auth_preflight_ready"
        return "auth_profile_not_logged_in"

    def _auth_readiness_result_from_state(
        self,
        state: dict[str, Any],
        *,
        action: str = "passive_auth_readiness",
        held_session: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        challenge_detected = bool(state.get("challenge_detected"))
        logged_in = bool(state.get("logged_in"))
        status = self._auth_readiness_status_from_state(state)
        result: dict[str, Any] = {
            "ok": bool(logged_in and not challenge_detected),
            "action": action,
            "status": status,
            "logged_in": logged_in,
            "release_blocking": bool(not logged_in or challenge_detected),
            "manual_login_required": bool(not logged_in and not challenge_detected),
            "profile_dir": self.config.profile_dir,
            "headless": self.config.headless,
            "url": self.config.project_url,
            "driver": self.driver_name,
            "debug": self.config.debug,
            "debug_artifact_dir": self.config.debug_artifact_dir,
            **state,
        }
        if held_session:
            now = time.monotonic()
            expires_at = float(held_session.get("expires_at_monotonic") or now)
            result["held_session"] = {
                "active": True,
                "session_key": held_session.get("session_key"),
                "created_at_monotonic": held_session.get("created_at_monotonic"),
                "expires_at_monotonic": expires_at,
                "seconds_until_expiry": max(0.0, round(expires_at - now, 3)),
                "ttl_seconds": held_session.get("ttl_seconds"),
            }
        return result

    async def _close_auth_readiness_held_session(self, session: dict[str, Any], *, reason: str) -> None:
        if session.get("closed"):
            return
        session["closed"] = True
        close_task = session.get("close_task")
        current_task = asyncio.current_task()
        if close_task is not None and close_task is not current_task:
            try:
                close_task.cancel()
            except Exception:
                pass
        context = session.get("context")
        playwright = session.get("playwright")
        operation_name = str(session.get("operation_name") or "auth_readiness")
        try:
            if context is not None:
                await self._finalize_context(context, operation_name)
        finally:
            if playwright is not None:
                try:
                    await playwright.stop()
                except Exception as exc:
                    self._log("driver", "failed to stop held playwright session", reason=reason, error=repr(exc))
            _PROFILE_LAST_CONTEXT_CLOSED_AT[self._profile_key] = time.monotonic()
            self._log("auth-readiness", "held auth readiness session closed", reason=reason, session_key=session.get("session_key"))

    async def _expire_auth_readiness_session_after(self, key: str, session: dict[str, Any], ttl_seconds: float) -> None:
        try:
            await asyncio.sleep(max(1.0, float(ttl_seconds)))
            async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
                current = _AUTH_READINESS_HELD_SESSIONS.get(key)
                if current is not session:
                    return
                _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
            await self._close_auth_readiness_held_session(session, reason="ttl_expired")
        except asyncio.CancelledError:
            return

    async def _held_auth_readiness_session(self) -> dict[str, Any] | None:
        key = self._auth_readiness_session_key()
        async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
            session = _AUTH_READINESS_HELD_SESSIONS.get(key)
            if session is None:
                return None
            if bool(session.get("closed")):
                _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
                return None
            expires_at = float(session.get("expires_at_monotonic") or 0.0)
            if expires_at and expires_at <= time.monotonic():
                _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
                await self._close_auth_readiness_held_session(session, reason="ttl_expired")
                return None
            return session

    def _auth_readiness_session_key_parts(self) -> tuple[str, str]:
        return (
            f"{self._profile_key}|",
            f"|{self.driver_name}|{self.config.browser_channel or 'default'}",
        )

    def _auth_readiness_session_is_compatible(self, key: str, session: dict[str, Any]) -> bool:
        if bool(session.get("closed")):
            return False
        prefix, suffix = self._auth_readiness_session_key_parts()
        return key.startswith(prefix) and key.endswith(suffix)

    async def _compatible_held_auth_readiness_session(self) -> tuple[str | None, dict[str, Any] | None, str]:
        """Return an active held auth session for this profile/driver/channel.

        The exact key includes the configured project URL.  In standard-browser
        validation the held auth-readiness probe may be created on
        https://chatgpt.com/ while a following ask targets a concrete Project or
        conversation URL.  Reuse is still safe when the profile, driver, and
        browser channel match; the ask operation will navigate the held page to
        its target URL before submitting.
        """

        preferred_key = self._auth_readiness_session_key()
        now = time.monotonic()
        expired: list[tuple[str, dict[str, Any]]] = []
        async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
            exact = _AUTH_READINESS_HELD_SESSIONS.get(preferred_key)
            if exact is not None and self._auth_readiness_session_is_compatible(preferred_key, exact):
                expires_at = float(exact.get("expires_at_monotonic") or 0.0)
                if expires_at and expires_at <= now:
                    _AUTH_READINESS_HELD_SESSIONS.pop(preferred_key, None)
                    expired.append((preferred_key, exact))
                else:
                    return preferred_key, exact, "exact_project_url"

            for key, session in list(_AUTH_READINESS_HELD_SESSIONS.items()):
                if not self._auth_readiness_session_is_compatible(key, session):
                    continue
                expires_at = float(session.get("expires_at_monotonic") or 0.0)
                if expires_at and expires_at <= now:
                    _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
                    expired.append((key, session))
                    continue
                return key, session, "compatible_profile_driver_channel"

        for key, session in expired:
            await self._close_auth_readiness_held_session(session, reason="ttl_expired")
        return None, None, "none"

    async def _any_active_held_auth_readiness_session_for_profile(self) -> tuple[str | None, dict[str, Any] | None]:
        key, session, _match = await self._compatible_held_auth_readiness_session()
        return key, session

    async def _remove_held_auth_readiness_session(self, key: str, session: dict[str, Any], *, reason: str) -> None:
        async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
            current = _AUTH_READINESS_HELD_SESSIONS.get(key)
            if current is session:
                _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
        await self._close_auth_readiness_held_session(session, reason=reason)

    async def _capture_auth_readiness_observation_artifacts(self, page: Any, result: dict[str, Any]) -> dict[str, Any]:
        if not bool(result.get("challenge_detected")):
            return result
        artifacts: list[str] = []
        status = str(result.get("status") or "auth_observation")
        base = self._artifact_dir / f"auth_readiness_{status}_{self._timestamp_for_filename()}"
        try:
            self._artifact_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        try:
            json_path = base.with_suffix(".json")
            await self._write_json(json_path, result)
            artifacts.append(str(json_path))
            self._log("artifact", "saved auth-readiness observation json", path=str(json_path))
        except Exception as exc:
            self._log("artifact", "failed to save auth-readiness observation json", error=str(exc))
        if self.config.save_html:
            try:
                html_path = base.with_suffix(".html")
                await self._write_text(html_path, await page.content())
                artifacts.append(str(html_path))
                self._log("artifact", "saved auth-readiness observation html", path=str(html_path))
            except Exception as exc:
                self._log("artifact", "failed to save auth-readiness observation html", error=str(exc))
        if self.config.save_screenshot:
            try:
                png_path = base.with_suffix(".png")
                await page.screenshot(path=str(png_path), full_page=True)
                artifacts.append(str(png_path))
                self._log("artifact", "saved auth-readiness observation screenshot", path=str(png_path))
            except Exception as exc:
                self._log("artifact", "failed to save auth-readiness observation screenshot", error=str(exc))
        if artifacts:
            result.setdefault("debug_artifacts", artifacts)
        return result

    async def _build_auth_readiness_launch_session(self, *, operation_name: str) -> tuple[Any, Any, Any]:
        Path(self.config.profile_dir).mkdir(parents=True, exist_ok=True)
        self._clear_profile_singleton_locks()
        self._log('rate-limit', 'skipping persisted conversation history cooldown for non-history operation', operation=operation_name)
        await self._respect_context_spacing()
        playwright_cm = await self._start_driver()
        playwright = await playwright_cm.start()
        browser_args = self._effective_browser_args()
        if self.config.disable_fedcm:
            browser_args.extend([
                "--disable-features=FedCm,FedCmAutoReauthn,FedCmWithoutThirdPartyCookies,FedCmIdpSigninStatusEnabled,FedCmIdpSigninStatusMetrics",
            ])
        ignore_default_args = []
        if self.config.filter_no_sandbox:
            ignore_default_args.extend(["--no-sandbox", "--disable-setuid-sandbox"])
        self._log(
            "driver",
            "launching persistent chromium context",
            disable_fedcm=self.config.disable_fedcm,
            filter_no_sandbox=self.config.filter_no_sandbox,
            no_viewport=self.config.no_viewport,
            channel=self.config.browser_channel or "default",
            running_as_root=(os.geteuid() == 0 if hasattr(os, "geteuid") else None),
            browser_args=browser_args,
            ignore_default_args=ignore_default_args,
            keep_open_session=True,
        )
        launch_kwargs = {
            "user_data_dir": self.config.profile_dir,
            "headless": self.config.headless,
            "channel": self.config.browser_channel,
            "slow_mo": self.config.slow_mo_ms,
            "accept_downloads": True,
            "args": browser_args,
            "ignore_default_args": ignore_default_args or None,
        }
        if self.config.no_viewport is True:
            launch_kwargs["no_viewport"] = True
            launch_kwargs["screen"] = {"width": self.config.viewport_width, "height": self.config.viewport_height}
        else:
            launch_kwargs["viewport"] = {"width": self.config.viewport_width, "height": self.config.viewport_height}
        context = await self._launch_persistent_context_with_recovery(playwright.chromium, launch_kwargs)
        context.set_default_timeout(self.config.navigation_timeout_ms)
        page = context.pages[0] if context.pages else await context.new_page()
        await self._install_conversation_history_request_shield(context, operation_name=operation_name)
        self._attach_context_debug(context, page, operation_name)
        return playwright, context, page

    async def _auth_readiness_session_status_for(self, key: str, session: dict[str, Any]) -> dict[str, Any]:
        page = session.get("page")
        try:
            state = await self._probe_auth_readiness_state(page)
            result = self._auth_readiness_result_from_state(
                state,
                action="auth_readiness_session_status",
                held_session=session,
            )
            result = await self._capture_auth_readiness_observation_artifacts(page, result)
            return self._attach_rate_limit_telemetry(result)
        except Exception as exc:
            async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
                current = _AUTH_READINESS_HELD_SESSIONS.get(key)
                if current is session:
                    _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
            await self._close_auth_readiness_held_session(session, reason="status_probe_failed")
            return {
                "ok": False,
                "action": "auth_readiness_session_status",
                "status": "held_session_probe_failed",
                "release_blocking": True,
                "error": str(exc),
                "error_type": type(exc).__name__,
                "held_session": {"active": False},
                "profile_dir": self.config.profile_dir,
            }

    async def auth_readiness_session_status(self) -> dict[str, Any]:
        session = await self._held_auth_readiness_session()
        if session is None:
            return {
                "ok": False,
                "action": "auth_readiness_session_status",
                "status": "no_held_auth_readiness_session",
                "held_session": {"active": False},
                "profile_dir": self.config.profile_dir,
                "release_blocking": True,
            }
        return await self._auth_readiness_session_status_for(self._auth_readiness_session_key(), session)

    def _locator_page(self, locator: Any) -> Any | None:
        page = getattr(locator, 'page', None)
        if page is not None:
            return page
        try:
            impl = getattr(locator, '_impl_obj', None)
            frame = getattr(impl, '_frame', None)
            page = getattr(frame, '_page', None)
            if page is not None:
                return page
        except Exception:
            return None
        return None

    async def _wait_for_rate_limit_modal_to_clear(
        self,
        page: Any,
        *,
        label: str,
        timeout_ms: int | None = None,
        respect_history_rate_limit_cooldown: bool = True,
    ) -> bool:
        timeout_ms = self.config.rate_limit_modal_wait_timeout_ms if timeout_ms is None else timeout_ms
        poll_interval_ms = self.config.rate_limit_modal_poll_interval_ms
        deadline = asyncio.get_running_loop().time() + (timeout_ms / 1000)
        saw_modal = False
        ack_wait_performed = False
        while True:
            modal = await self._find_visible_locator(page, RATE_LIMIT_MODAL_SELECTORS, label=f'{label}-rate-limit-modal')
            if modal is None:
                if saw_modal:
                    self._log('rate-limit', 'rate limit modal cleared', label=label)
                    if respect_history_rate_limit_cooldown and not ack_wait_performed:
                        await self._respect_rate_limit_cooldown()
                    elif respect_history_rate_limit_cooldown and ack_wait_performed:
                        self._record_rate_limit_event(
                            kind='cooldown_wait_satisfied_by_modal_ack_wait',
                            trigger='modal_ack',
                            label=label,
                            wait_seconds=0.0,
                        )
                        self._log(
                            'rate-limit',
                            'persisted conversation history cooldown satisfied by modal acknowledgement wait',
                            label=label,
                            cooldown_remaining=round(self._conversation_history_cooldown_remaining(), 3),
                        )
                    else:
                        self._record_rate_limit_event(
                            kind='cooldown_wait_skipped',
                            trigger='non_history_operation',
                            label=label,
                            wait_seconds=self._conversation_history_cooldown_remaining(),
                        )
                        self._log(
                            'rate-limit',
                            'skipping persisted conversation history cooldown after modal clear for non-history operation',
                            label=label,
                            cooldown_remaining=round(self._conversation_history_cooldown_remaining(), 3),
                        )
                return saw_modal
            if not saw_modal:
                saw_modal = True
                current_url = await self._safe_page_url(page)
                self._record_rate_limit_event(kind='modal_detected', trigger='modal', status=429, url=current_url, label=label)
                self._note_conversation_history_rate_limit(
                    trigger='modal',
                    url=current_url,
                    status=429,
                )
                self._log('rate-limit', 'rate limit modal detected', label=label, current_url=current_url, timeout_ms=timeout_ms)
            ack = await self._find_visible_locator(page, RATE_LIMIT_MODAL_ACK_SELECTORS, label=f'{label}-rate-limit-ack')
            if ack is not None:
                try:
                    await self._click_locator_with_fallback(
                        ack,
                        label=f'{label}-rate-limit-ack',
                        timeout_ms=min(5_000, timeout_ms),
                        handle_rate_limit=False,
                    )
                    self._record_rate_limit_event(kind='modal_acknowledged', trigger='modal_ack', label=label, wait_seconds=0.0)
                    if respect_history_rate_limit_cooldown and not ack_wait_performed:
                        await self._wait_after_rate_limit_modal_ack(label=label)
                        ack_wait_performed = True
                        deadline = max(
                            deadline,
                            asyncio.get_running_loop().time() + max(1.0, poll_interval_ms / 1000),
                        )
                except Exception as exc:
                    self._log('rate-limit', 'rate limit modal acknowledgement click failed', label=label, error=repr(exc))
            if asyncio.get_running_loop().time() >= deadline:
                snapshot = await self._rate_limit_modal_snapshot(page, label=f'{label}-timeout')
                raise RateLimitDetectedError(
                    'Rate limit modal did not clear before continuing',
                    retry_after_seconds=None,
                    cooldown_remaining_seconds=self._conversation_history_cooldown_remaining(),
                    modal_text=snapshot.get('text') if isinstance(snapshot, dict) else None,
                    payload={
                        'modal': snapshot,
                        'cooldown': self._rate_limit_cooldown_snapshot(),
                        'rate_limit_telemetry': self._rate_limit_telemetry_snapshot(),
                    },
                )
            await page.wait_for_timeout(poll_interval_ms)

    async def _rate_limit_modal_snapshot(self, page: Any, *, label: str = 'rate-limit-diagnostic') -> dict[str, Any]:
        probes: list[dict[str, Any]] = []
        for selector in RATE_LIMIT_MODAL_SELECTORS:
            try:
                locator = page.locator(selector)
                count = await locator.count()
            except Exception as exc:
                probes.append({'selector': selector, 'count': 0, 'visible': False, 'error': repr(exc)})
                continue
            visible = False
            text = ''
            if count:
                try:
                    first = locator.first
                    visible = bool(await first.is_visible(timeout=250))
                    if visible:
                        text = (await first.inner_text(timeout=750)).strip()
                except Exception as exc:
                    probes.append({'selector': selector, 'count': count, 'visible': False, 'error': repr(exc)})
                    continue
            probe = {
                'selector': selector,
                'count': count,
                'visible': visible,
            }
            if text:
                probe['text'] = re.sub(r'\s+', ' ', text)[:1000]
            probes.append(probe)
            if visible:
                return {
                    'detected': True,
                    'selector': selector,
                    'text': probe.get('text', ''),
                    'probes': probes,
                    'label': label,
                }
        return {
            'detected': False,
            'selector': None,
            'text': '',
            'probes': probes,
            'label': label,
        }

    async def run_login_check(self, keep_open: bool = False) -> dict[str, Any]:
        self._log(
            "login-check",
            "starting login check",
            project_url=self.config.project_url,
            profile_dir=self.config.profile_dir,
            headless=self.config.headless,
            driver=self.driver_name,
            channel=self.config.browser_channel or "default",
            keep_open=keep_open,
        )
        return await self._run_with_context(
            operation_name="login_check",
            operation=self._run_login_check_operation,
            keep_open=keep_open,
        )

    async def run_passive_auth_readiness(self, keep_open: bool = False) -> dict[str, Any]:
        self._log(
            "auth-readiness",
            "starting passive auth readiness check",
            project_url=self.config.project_url,
            profile_dir=self.config.profile_dir,
            headless=self.config.headless,
            driver=self.driver_name,
            channel=self.config.browser_channel or "default",
            keep_open=keep_open,
        )
        existing_key, existing_session, existing_match = await self._compatible_held_auth_readiness_session()
        if existing_session is not None and existing_key is not None:
            if keep_open:
                existing_session["expires_at_monotonic"] = time.monotonic() + self._auth_readiness_keep_open_seconds()
                existing_session["ttl_seconds"] = self._auth_readiness_keep_open_seconds()
                self._log(
                    "auth-readiness",
                    "extended compatible held auth-readiness browser session",
                    session_key=existing_session.get("session_key"),
                    match_mode=existing_match,
                    requested_project_url=self.config.project_url,
                )
            self._log(
                "auth-readiness",
                "reusing compatible held auth-readiness browser session for readiness check",
                session_key=existing_session.get("session_key"),
                match_mode=existing_match,
                requested_project_url=self.config.project_url,
            )
            return await self._auth_readiness_session_status_for(existing_key, existing_session)
        if keep_open:
            return await self._run_passive_auth_readiness_keep_open()
        return await self._run_with_context(
            operation_name="auth_readiness",
            operation=self._run_passive_auth_readiness_operation,
            keep_open=keep_open,
            respect_history_rate_limit_cooldown=False,
        )

    async def ask_question(
        self,
        prompt: str,
        file_path: Optional[str] = None,
        attachment_paths: Optional[list[str]] = None,
        expect_json: bool = False,
        keep_open: bool = False,
        service_timeout_seconds: Optional[float] = None,
        prefer_button_submit: bool = False,
    ) -> Any:
        result = await self.ask_question_result(
            prompt=prompt,
            file_path=file_path,
            attachment_paths=attachment_paths,
            expect_json=expect_json,
            keep_open=keep_open,
            service_timeout_seconds=service_timeout_seconds,
            prefer_button_submit=prefer_button_submit,
        )
        return result["answer"]

    async def ask_question_result(
        self,
        prompt: str,
        file_path: Optional[str] = None,
        attachment_paths: Optional[list[str]] = None,
        conversation_url: str | None = None,
        expect_json: bool = False,
        keep_open: bool = False,
        service_timeout_seconds: Optional[float] = None,
        prefer_button_submit: bool = False,
    ) -> dict[str, Any]:
        self._clear_ask_progress()
        self._record_ask_progress(
            action="ask",
            status="ask_started",
            prompt_length=len(prompt),
            conversation_url=conversation_url,
            expect_json=expect_json,
            service_timeout_seconds=service_timeout_seconds,
        )
        self._log(
            "ask",
            "starting ask_question",
            project_url=self.config.project_url,
            profile_dir=self.config.profile_dir,
            headless=self.config.headless,
            driver=self.driver_name,
            prompt_length=len(prompt),
            file_path=file_path,
            attachment_paths=attachment_paths,
            expect_json=expect_json,
            keep_open=keep_open,
        )
        held_result = await self._try_ask_question_with_held_auth_ready_session(
            prompt=prompt,
            file_path=file_path,
            attachment_paths=attachment_paths,
            conversation_url=conversation_url,
            expect_json=expect_json,
            keep_open=keep_open,
            service_timeout_seconds=service_timeout_seconds,
            prefer_button_submit=prefer_button_submit,
        )
        if held_result is not None:
            return held_result
        return await self._run_with_context(
            operation_name="ask_question",
            operation=self._ask_question_operation,
            prompt=prompt,
            file_path=file_path,
            attachment_paths=attachment_paths,
            conversation_url=conversation_url,
            expect_json=expect_json,
            keep_open=keep_open,
            service_timeout_seconds=service_timeout_seconds,
            prefer_button_submit=prefer_button_submit,
        )

    async def _try_ask_question_with_held_auth_ready_session(
        self,
        *,
        prompt: str,
        file_path: Optional[str],
        attachment_paths: Optional[list[str]],
        conversation_url: str | None,
        expect_json: bool,
        keep_open: bool,
        service_timeout_seconds: Optional[float],
        prefer_button_submit: bool,
    ) -> dict[str, Any] | None:
        session_key, session, match_mode = await self._compatible_held_auth_readiness_session()
        if session is None or session_key is None:
            self._log(
                "ask",
                "no held auth-readiness session available before ask; launching normal browser context",
                profile_dir=self.config.profile_dir,
                driver=self.driver_name,
                browser_channel=self.config.browser_channel or "default",
            )
            return None

        context = session.get("context")
        page = session.get("page")
        if context is None or page is None:
            await self._remove_held_auth_readiness_session(session_key, session, reason="ask_reuse_missing_context_or_page")
            return {
                "ok": False,
                "action": "ask",
                "status": "held_auth_ready_session_invalid",
                "error": "held auth-readiness session had no context/page; closed it instead of launching a competing browser context",
                "error_type": "held_auth_ready_session_invalid",
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "release_blocking": True,
            }

        try:
            state = await self._probe_auth_readiness_state(page)
            status = self._auth_readiness_status_from_state(state)
            session_status = self._auth_readiness_result_from_state(
                state,
                action="ask_preflight_held_auth_readiness_session_status",
                held_session=session,
            )
            session_status = self._attach_rate_limit_telemetry(session_status)
        except Exception as exc:
            await self._remove_held_auth_readiness_session(session_key, session, reason="ask_preflight_probe_failed")
            return {
                "ok": False,
                "action": "ask",
                "status": "held_auth_ready_session_probe_failed",
                "error": f"held auth-readiness session probe failed before ask: {type(exc).__name__}: {exc}",
                "error_type": type(exc).__name__,
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "release_blocking": True,
            }

        if not (
            status == "auth_preflight_ready"
            and bool(session_status.get("logged_in"))
            and not bool(session_status.get("challenge_detected"))
        ):
            await self._remove_held_auth_readiness_session(session_key, session, reason=f"ask_preflight_{status}")
            return {
                "ok": False,
                "action": "ask",
                "status": "held_auth_ready_session_not_ready",
                "error": "held auth-readiness session was challenged/stale before ask; closed it instead of launching a competing browser context",
                "error_type": "held_auth_ready_session_not_ready",
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "held_session_status": session_status,
                "release_blocking": True,
                "recovery_hint": "Run the standard browser auth-readiness bootstrap/check again before retrying pb ask.",
            }

        self._log(
            "ask",
            "reusing held auth-readiness browser session for ask_question",
            session_key=session_key,
            match_mode=match_mode,
            profile_dir=self.config.profile_dir,
            target_url=conversation_url or self.config.project_url,
        )

        try:
            result = await self._ask_question_operation(
                context=context,
                page=page,
                prompt=prompt,
                file_path=file_path,
                attachment_paths=attachment_paths,
                conversation_url=conversation_url,
                expect_json=expect_json,
                keep_open=keep_open,
                service_timeout_seconds=service_timeout_seconds,
                prefer_button_submit=prefer_button_submit,
                reuse_current_page_if_ready=True,
            )
            if isinstance(result, dict):
                result.setdefault("held_session_reused", True)
                result.setdefault("held_session_match_mode", match_mode)
                result.setdefault("held_session_key", session_key)
                result.setdefault("held_session_status", session_status)
                result = self._attach_rate_limit_telemetry(result)
            self._log("result", "ask_question completed via held auth-readiness session", result_type=type(result).__name__)
            return result
        except Exception as exc:
            current_url = await self._safe_page_url(page)
            self._log(
                "error",
                "ask_question failed while reusing held auth-readiness session",
                error_type=type(exc).__name__,
                error=str(exc),
                current_url=current_url,
                session_key=session_key,
            )
            await self._dump_failure_artifacts(page, "ask_question_held_session", exc)
            raise

    async def release_live_bootstrap_and_ask(
        self,
        *,
        project_name: str,
        bootstrap_prompt: str,
        ask_prompt: str,
        icon: Optional[str] = None,
        color: Optional[str] = None,
        memory_mode: str = "project-only",
        service_timeout_seconds: Optional[float] = None,
        warmup_conversation_url: Optional[str] = None,
    ) -> dict[str, Any]:
        """Run release-live project ensure, bootstrap, and first ask in one browser context.

        Release-live validation should behave like one human browser session: select
        the project, create the fresh conversation, and send the first validation
        prompt without closing/reopening the browser between those operations.
        When the live preflight has already proven a concrete Project conversation
        URL for this exact slot profile, start the initial auth check at that URL
        instead of warming up on the bare chatgpt.com root.
        """
        effective_warmup_url = str(warmup_conversation_url or "").strip() or None
        self._log(
            "release-live-continuous",
            "starting release-live continuous bootstrap and ask",
            project_name=project_name,
            profile_dir=self.config.profile_dir,
            warmup_conversation_url=effective_warmup_url,
            warmup_strategy="trusted_preflight_conversation_url" if effective_warmup_url else "configured_project_url",
        )
        original_project_url = self.config.project_url
        if effective_warmup_url:
            self.config.project_url = effective_warmup_url
        try:
            return await self._run_with_context(
                operation_name="release_live_continuous",
                operation=self._release_live_bootstrap_and_ask_operation,
                project_name=project_name,
                bootstrap_prompt=bootstrap_prompt,
                ask_prompt=ask_prompt,
                icon=icon,
                color=color,
                memory_mode=memory_mode,
                service_timeout_seconds=service_timeout_seconds,
                warmup_conversation_url=effective_warmup_url,
                respect_history_rate_limit_cooldown=False,
            )
        finally:
            self.config.project_url = original_project_url

    @staticmethod
    def _release_live_expected_single_token(prompt: Any) -> str:
        text = str(prompt or "").strip()
        marker = "single token "
        if marker not in text:
            return ""
        tail = text.split(marker, 1)[1].strip()
        for suffix in (" and nothing else.", " and nothing else"):
            if tail.endswith(suffix):
                tail = tail[: -len(suffix)].strip()
                break
        return tail.strip().strip('"\'`')

    @staticmethod
    def _release_live_result_answer_text(result: Any) -> str:
        if not isinstance(result, dict):
            return ""
        for key in ("answer", "answer_text", "text", "response_text"):
            value = result.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return ""

    _RELEASE_LIVE_VISIBLE_THINKING_PREAMBLES = {
        "Thought for a couple of seconds",
        "Thought for a few seconds",
    }

    @classmethod
    def _release_live_answer_matches_expected_single_token(cls, answer: Any, expected: Any) -> bool:
        """Return True only for an exact sentinel, with bounded visible-thinking normalization.

        Some ChatGPT surfaces render a short visible thinking preamble before a
        requested single-token answer, for example ``Thought for a couple of
        seconds`` followed by the sentinel on the last line.  For release-live
        sentinel validation only, accept that bounded shape when every non-empty
        line before the sentinel is one of the known preambles.  Any other extra
        text remains a failure.
        """

        expected_text = str(expected or "").strip()
        answer_text = str(answer or "").strip()
        if not expected_text or not answer_text:
            return False
        if answer_text == expected_text:
            return True

        lines = [line.strip() for line in answer_text.splitlines() if line.strip()]
        if not lines or lines[-1] != expected_text:
            return False
        prefix_lines = lines[:-1]
        return bool(prefix_lines) and all(line in cls._RELEASE_LIVE_VISIBLE_THINKING_PREAMBLES for line in prefix_lines)

    @classmethod
    def _release_live_result_completed_with_expected_token(cls, result: Any, prompt: Any) -> bool:
        if not isinstance(result, dict):
            return False
        status = str(result.get("status") or "").strip().lower()
        if status != "completed":
            return False
        expected = cls._release_live_expected_single_token(prompt)
        if not expected:
            return False
        answer = cls._release_live_result_answer_text(result)
        return cls._release_live_answer_matches_expected_single_token(answer, expected)

    @staticmethod
    def _release_live_telemetry_guardrail_seen(telemetry: Any) -> bool:
        if not isinstance(telemetry, dict):
            return False
        return bool(
            telemetry.get("rate_limit_modal_detected")
            or telemetry.get("conversation_history_429_seen")
            or telemetry.get("backend_api_guardrail_seen")
        )

    @staticmethod
    def _release_live_telemetry_guardrail_seen_since(telemetry: Any, event_start_index: int) -> bool:
        if not isinstance(telemetry, dict):
            return False
        events = telemetry.get("service_rate_limit_events")
        if not isinstance(events, list):
            return False
        try:
            start = max(0, int(event_start_index))
        except Exception:
            start = 0
        for event in events[start:]:
            if not isinstance(event, dict):
                continue
            if event.get("kind") in {"backend_api_guardrail", "modal_detected", "conversation_history_rate_limit"}:
                return True
            try:
                if int(event.get("status") or 0) == 429:
                    return True
            except Exception:
                pass
        return False

    @staticmethod
    def _release_live_guardrail_cooldown_seconds() -> float:
        raw = (os.getenv("PROMPTBRANCH_RELEASE_LIVE_BOOTSTRAP_GUARDRAIL_COOLDOWN_SECONDS") or "60").strip()
        try:
            seconds = float(raw)
        except Exception:
            seconds = 60.0
        # The retry is a bounded backoff, not a bypass: at most one minute by default
        # and hard-capped to five minutes for operator-tuned release validation.
        return min(300.0, max(0.0, seconds))

    async def _release_live_bootstrap_retry_readiness_gate(
        self,
        page: Any,
        *,
        target_url: str,
        label: str,
        action: str,
        wait_seconds: float = 0.0,
    ) -> dict[str, Any]:
        wait_seconds = min(300.0, max(0.0, float(wait_seconds or 0.0)))
        if wait_seconds > 0:
            self._rate_limit_cooldown_wait_seconds_total += wait_seconds
            self._rate_limit_cooldown_wait_count += 1
            self._record_rate_limit_event(
                kind="release_live_bootstrap_guardrail_cooldown_wait",
                trigger="release_live_bootstrap_guardrail",
                label=label,
                wait_seconds=wait_seconds,
            )
            self._log(
                "release-live-continuous",
                "waiting before one safe release-live bootstrap retry",
                label=label,
                wait_seconds=round(wait_seconds, 3),
                retry_limit=1,
                bypass=False,
            )
            await asyncio.sleep(wait_seconds)

        await self._wait_for_challenge_resolution(page, label=f"{label}-rereadiness")
        await self._raise_fail_fast_challenge_if_configured(page, stage=f"{label}-rereadiness")
        state = await self._probe_auth_readiness_state(page)
        status = self._auth_readiness_status_from_state(state)
        readiness = self._auth_readiness_result_from_state(
            state,
            action=action,
            held_session=None,
        )
        scope = self._ask_target_scope_evidence(
            current_url=str(readiness.get("current_url") or await self._safe_page_url(page)),
            target_url=target_url,
        )
        ready = bool(
            status == "auth_preflight_ready"
            and bool(readiness.get("composer_visible"))
            and bool(readiness.get("logged_in"))
            and not bool(readiness.get("challenge_detected"))
            and scope.get("matches") is True
        )
        result = {
            "ok": ready,
            "action": action,
            "status": "ready_for_single_bootstrap_retry" if ready else "not_ready_for_bootstrap_retry",
            "label": label,
            "wait_seconds": round(wait_seconds, 3),
            "retry_limit": 1,
            "bypass": False,
            "readiness": readiness,
            "scope": scope,
        }
        self._log(
            "release-live-continuous",
            "release-live bootstrap retry readiness checked",
            label=label,
            ready=ready,
            status=status,
            current_url=readiness.get("current_url"),
            challenge_detected=readiness.get("challenge_detected"),
            composer_visible=readiness.get("composer_visible"),
            logged_in=readiness.get("logged_in"),
            scope_matches=scope.get("matches"),
            bypass=False,
        )
        return self._attach_rate_limit_telemetry(result)

    async def _release_live_guardrail_cooldown_and_recheck(
        self,
        page: Any,
        *,
        target_url: str,
        label: str,
    ) -> dict[str, Any]:
        configured_wait = self._release_live_guardrail_cooldown_seconds()
        persisted_remaining = self._conversation_history_cooldown_remaining()
        wait_seconds = max(configured_wait, persisted_remaining)
        wait_seconds = min(300.0, max(0.0, wait_seconds))
        return await self._release_live_bootstrap_retry_readiness_gate(
            page,
            target_url=target_url,
            label=label,
            action="release_live_bootstrap_guardrail_cooldown_retry_gate",
            wait_seconds=wait_seconds,
        )

    async def _release_live_bootstrap_sentinel_retry_gate(
        self,
        page: Any,
        *,
        target_url: str,
        label: str = "bootstrap_sentinel_missing_after_ask_success",
    ) -> dict[str, Any]:
        return await self._release_live_bootstrap_retry_readiness_gate(
            page,
            target_url=target_url,
            label=label,
            action="release_live_bootstrap_sentinel_retry_gate",
            wait_seconds=0.0,
        )

    async def _release_live_bootstrap_and_ask_operation(
        self,
        *,
        context: Any,
        page: Any,
        project_name: str,
        bootstrap_prompt: str,
        ask_prompt: str,
        icon: Optional[str],
        color: Optional[str],
        memory_mode: str,
        service_timeout_seconds: Optional[float] = None,
        warmup_conversation_url: Optional[str] = None,
    ) -> dict[str, Any]:
        started = time.monotonic()
        direct_conversation_url = str(warmup_conversation_url or "").strip() if warmup_conversation_url else ""
        direct_conversation_mode = bool(direct_conversation_url and self._is_project_scoped_conversation_url(direct_conversation_url))
        if direct_conversation_mode:
            project_url = self._project_home_url_from_url(direct_conversation_url)
            project_result = {
                "ok": True,
                "action": "project_ensure",
                "status": "trusted_conversation_url",
                "project_url": project_url,
                "conversation_url": direct_conversation_url,
                "project_name": project_name,
                "project_identity_source": "warmup_conversation_url",
                "project_discovery_skipped": True,
                "root_project_discovery_skipped": True,
                "project_created": False,
                "project_removed": False,
            }
            self._log(
                "release-live-continuous",
                "using trusted project conversation URL directly; skipping root project discovery",
                project_name=project_name,
                project_url=project_url,
                conversation_url=direct_conversation_url,
                project_identity_source="warmup_conversation_url",
            )
        else:
            project_result = await self._ensure_project_operation(
                context=context,
                page=page,
                name=project_name,
                icon=icon,
                color=color,
                memory_mode=memory_mode,
                keep_open=False,
            )
            project_result = self._attach_rate_limit_telemetry(project_result)
            project_url = project_result.get("project_url") if isinstance(project_result, dict) else None
            if not (isinstance(project_result, dict) and project_result.get("ok") and isinstance(project_url, str) and project_url):
                return {
                    "ok": False,
                    "action": "test_release_live_continuous",
                    "status": str(project_result.get("status") or "live_project_ensure_failed") if isinstance(project_result, dict) else "live_project_ensure_failed",
                    "failed_phase": "live_project_ensure",
                    "project_result": project_result,
                    "warmup_conversation_url": warmup_conversation_url,
                    "warmup_strategy": "trusted_preflight_conversation_url" if warmup_conversation_url else "configured_project_url",
                    "trusted_conversation_direct_mode": False,
                    "duration_seconds": round(time.monotonic() - started, 3),
                }

        bootstrap_target_url = direct_conversation_url if direct_conversation_mode else project_url
        if direct_conversation_mode:
            direct_nav = await self._goto(
                page,
                direct_conversation_url,
                label="release-live-continuous-trusted-conversation",
                respect_history_rate_limit_cooldown=False,
            )
            await self._wait_for_challenge_resolution(page, label="release-live-continuous-trusted-conversation")
            await self._raise_fail_fast_challenge_if_configured(page, stage="release-live-continuous-trusted-conversation")
            direct_state = await self._probe_auth_readiness_state(page)
            direct_status = self._auth_readiness_status_from_state(direct_state)
            direct_readiness = self._auth_readiness_result_from_state(
                direct_state,
                action="release_live_continuous_trusted_conversation_status",
                held_session=None,
            )
            direct_scope = self._ask_target_scope_evidence(
                current_url=str(direct_readiness.get("current_url") or await self._safe_page_url(page)),
                target_url=direct_conversation_url,
            )
            project_result["trusted_conversation_navigation"] = direct_nav
            project_result["trusted_conversation_readiness"] = direct_readiness
            project_result["trusted_conversation_scope"] = direct_scope
            project_result["trusted_conversation_ready"] = bool(
                direct_status == "auth_preflight_ready"
                and bool(direct_readiness.get("composer_visible"))
                and bool(direct_readiness.get("logged_in"))
                and not bool(direct_readiness.get("challenge_detected"))
                and direct_scope.get("matches") is True
            )
            self._log(
                "release-live-continuous",
                "trusted conversation page readiness checked before bootstrap ask",
                status=direct_status,
                ready=project_result["trusted_conversation_ready"],
                current_url=direct_readiness.get("current_url"),
                requested_target_url=direct_conversation_url,
                composer_visible=direct_readiness.get("composer_visible"),
                logged_in=direct_readiness.get("logged_in"),
                challenge_detected=direct_readiness.get("challenge_detected"),
                scope_matches=direct_scope.get("matches"),
                scope_reason=direct_scope.get("reason"),
            )
            if not project_result["trusted_conversation_ready"]:
                return {
                    "ok": False,
                    "action": "test_release_live_continuous",
                    "status": "trusted_conversation_not_ready",
                    "failed_phase": "live_conversation_bootstrap",
                    "project_url": project_url,
                    "conversation_url": direct_conversation_url,
                    "project_result": project_result,
                    "trusted_conversation_navigation": direct_nav,
                    "trusted_conversation_readiness": direct_readiness,
                    "trusted_conversation_scope": direct_scope,
                    "warmup_conversation_url": warmup_conversation_url,
                    "warmup_strategy": "trusted_preflight_conversation_url",
                    "trusted_conversation_direct_mode": True,
                    "root_project_discovery_skipped": True,
                    "duration_seconds": round(time.monotonic() - started, 3),
                }
        pre_bootstrap_event_start = len(self._rate_limit_events)
        pre_bootstrap_telemetry = self._rate_limit_telemetry_snapshot()
        pre_bootstrap_retry_gate: dict[str, Any] | None = None
        if self._release_live_telemetry_guardrail_seen_since(pre_bootstrap_telemetry, pre_bootstrap_event_start):
            pre_bootstrap_retry_gate = await self._release_live_guardrail_cooldown_and_recheck(
                page,
                target_url=bootstrap_target_url,
                label="pre_bootstrap_guardrail",
            )
            if not bool(pre_bootstrap_retry_gate.get("ok")):
                return {
                    "ok": False,
                    "action": "test_release_live_continuous",
                    "status": "live_bootstrap_guardrail",
                    "failed_phase": "live_conversation_bootstrap",
                    "project_url": project_url,
                    "conversation_url": direct_conversation_url if direct_conversation_mode else None,
                    "project_result": project_result,
                    "bootstrap_guardrail_retry": pre_bootstrap_retry_gate,
                    "rate_limit_telemetry": pre_bootstrap_retry_gate.get("rate_limit_telemetry"),
                    "warmup_conversation_url": warmup_conversation_url,
                    "warmup_strategy": "trusted_preflight_conversation_url" if warmup_conversation_url else "configured_project_url",
                    "trusted_conversation_direct_mode": direct_conversation_mode,
                    "duration_seconds": round(time.monotonic() - started, 3),
                }

        original_project_url = self.config.project_url
        bootstrap_event_start = len(self._rate_limit_events)
        try:
            self.config.project_url = project_url
            bootstrap_result = await self._ask_question_operation(
                context=context,
                page=page,
                prompt=bootstrap_prompt,
                file_path=None,
                attachment_paths=None,
                conversation_url=bootstrap_target_url,
                expect_json=False,
                keep_open=False,
                service_timeout_seconds=service_timeout_seconds,
                prefer_button_submit=False,
                reuse_current_page_if_ready=direct_conversation_mode,
            )
            bootstrap_result = self._attach_rate_limit_telemetry(bootstrap_result)
        finally:
            self.config.project_url = original_project_url

        bootstrap_telemetry = bootstrap_result.get("rate_limit_telemetry") if isinstance(bootstrap_result, dict) else None
        conversation_url = bootstrap_result.get("conversation_url") if isinstance(bootstrap_result, dict) else None
        if direct_conversation_mode and not (isinstance(conversation_url, str) and "/c/" in conversation_url):
            conversation_url = direct_conversation_url
        bootstrap_guardrail_retry: dict[str, Any] | None = pre_bootstrap_retry_gate
        if self._release_live_telemetry_guardrail_seen_since(bootstrap_telemetry, bootstrap_event_start):
            bootstrap_guardrail_retry = await self._release_live_guardrail_cooldown_and_recheck(
                page,
                target_url=bootstrap_target_url,
                label="bootstrap_guardrail_retry",
            )
            if bool(bootstrap_guardrail_retry.get("ok")):
                retry_event_start = len(self._rate_limit_events)
                original_project_url = self.config.project_url
                try:
                    self.config.project_url = project_url
                    retry_bootstrap_result = await self._ask_question_operation(
                        context=context,
                        page=page,
                        prompt=bootstrap_prompt,
                        file_path=None,
                        attachment_paths=None,
                        conversation_url=bootstrap_target_url,
                        expect_json=False,
                        keep_open=False,
                        service_timeout_seconds=service_timeout_seconds,
                        prefer_button_submit=False,
                        reuse_current_page_if_ready=direct_conversation_mode,
                    )
                    retry_bootstrap_result = self._attach_rate_limit_telemetry(retry_bootstrap_result)
                finally:
                    self.config.project_url = original_project_url
                retry_telemetry = retry_bootstrap_result.get("rate_limit_telemetry") if isinstance(retry_bootstrap_result, dict) else None
                retry_conversation_url = retry_bootstrap_result.get("conversation_url") if isinstance(retry_bootstrap_result, dict) else None
                if direct_conversation_mode and not (isinstance(retry_conversation_url, str) and "/c/" in retry_conversation_url):
                    retry_conversation_url = direct_conversation_url
                bootstrap_guardrail_retry["retry_attempted"] = True
                bootstrap_guardrail_retry["retry_result_status"] = str(retry_bootstrap_result.get("status") or "") if isinstance(retry_bootstrap_result, dict) else "non_dict_result"
                bootstrap_guardrail_retry["retry_conversation_url"] = retry_conversation_url
                if not self._release_live_telemetry_guardrail_seen_since(retry_telemetry, retry_event_start):
                    bootstrap_result = retry_bootstrap_result
                    bootstrap_telemetry = retry_telemetry
                    conversation_url = retry_conversation_url
                else:
                    bootstrap_guardrail_retry["retry_guardrail_persisted"] = True
            else:
                bootstrap_guardrail_retry["retry_attempted"] = False

        if self._release_live_telemetry_guardrail_seen_since(bootstrap_telemetry, bootstrap_event_start) and not (
            isinstance(bootstrap_guardrail_retry, dict)
            and bool(bootstrap_guardrail_retry.get("retry_attempted"))
            and not bool(bootstrap_guardrail_retry.get("retry_guardrail_persisted"))
        ):
            return {
                "ok": False,
                "action": "test_release_live_continuous",
                "status": "live_bootstrap_guardrail",
                "failed_phase": "live_conversation_bootstrap",
                "project_url": project_url,
                "conversation_url": conversation_url,
                "project_result": project_result,
                "bootstrap_result": bootstrap_result,
                "bootstrap_guardrail_retry": bootstrap_guardrail_retry,
                "rate_limit_telemetry": bootstrap_telemetry,
                "warmup_conversation_url": warmup_conversation_url,
                "warmup_strategy": "trusted_preflight_conversation_url" if warmup_conversation_url else "configured_project_url",
                "trusted_conversation_direct_mode": direct_conversation_mode,
                "duration_seconds": round(time.monotonic() - started, 3),
            }
        if not (isinstance(conversation_url, str) and "/c/" in conversation_url):
            return {
                "ok": False,
                "action": "test_release_live_continuous",
                "status": "live_conversation_url_missing",
                "failed_phase": "live_conversation_bootstrap",
                "project_url": project_url,
                "conversation_url": conversation_url,
                "project_result": project_result,
                "bootstrap_result": bootstrap_result,
                "warmup_conversation_url": warmup_conversation_url,
                "warmup_strategy": "trusted_preflight_conversation_url" if warmup_conversation_url else "configured_project_url",
                "trusted_conversation_direct_mode": direct_conversation_mode,
                "duration_seconds": round(time.monotonic() - started, 3),
            }

        ask_result = await self._ask_question_operation(
            context=context,
            page=page,
            prompt=ask_prompt,
            file_path=None,
            attachment_paths=None,
            conversation_url=conversation_url,
            expect_json=False,
            keep_open=False,
            service_timeout_seconds=service_timeout_seconds,
            prefer_button_submit=False,
            reuse_current_page_if_ready=True,
        )
        ask_result = self._attach_rate_limit_telemetry(ask_result)
        ask_status = str(ask_result.get("status") or "") if isinstance(ask_result, dict) else ""
        ask_challenge_type = str(ask_result.get("challenge_type") or ask_result.get("response_challenge_type") or "") if isinstance(ask_result, dict) else ""
        bootstrap_ok = bool(isinstance(bootstrap_result, dict) and bootstrap_result.get("ok"))
        ask_ok = bool(isinstance(ask_result, dict) and ask_result.get("ok"))
        bootstrap_completed_with_expected_token = self._release_live_result_completed_with_expected_token(
            bootstrap_result,
            bootstrap_prompt,
        )
        ask_completed_with_expected_token = self._release_live_result_completed_with_expected_token(
            ask_result,
            ask_prompt,
        )
        bootstrap_sentinel_retry: dict[str, Any] | None = None
        if (not bootstrap_completed_with_expected_token) and ask_completed_with_expected_token:
            bootstrap_sentinel_retry = await self._release_live_bootstrap_sentinel_retry_gate(
                page,
                target_url=conversation_url,
            )
            if bool(bootstrap_sentinel_retry.get("ok")):
                retry_bootstrap_result = await self._ask_question_operation(
                    context=context,
                    page=page,
                    prompt=bootstrap_prompt,
                    file_path=None,
                    attachment_paths=None,
                    conversation_url=conversation_url,
                    expect_json=False,
                    keep_open=False,
                    service_timeout_seconds=service_timeout_seconds,
                    prefer_button_submit=False,
                    reuse_current_page_if_ready=True,
                )
                retry_bootstrap_result = self._attach_rate_limit_telemetry(retry_bootstrap_result)
                bootstrap_sentinel_retry["retry_attempted"] = True
                bootstrap_sentinel_retry["retry_result_status"] = str(retry_bootstrap_result.get("status") or "") if isinstance(retry_bootstrap_result, dict) else "non_dict_result"
                bootstrap_sentinel_retry["retry_completed_with_expected_sentinel"] = self._release_live_result_completed_with_expected_token(
                    retry_bootstrap_result,
                    bootstrap_prompt,
                )
                bootstrap_sentinel_retry["retry_result"] = retry_bootstrap_result
                if bool(bootstrap_sentinel_retry.get("retry_completed_with_expected_sentinel")):
                    bootstrap_result = retry_bootstrap_result
                    bootstrap_completed_with_expected_token = True
                    bootstrap_ok = True
            else:
                bootstrap_sentinel_retry["retry_attempted"] = False

        sentinel_completed_ok = bool(
            isinstance(project_result, dict)
            and project_result.get("ok")
            and bootstrap_completed_with_expected_token
            and ask_completed_with_expected_token
        )
        if ask_status == "docker_live_profile_challenged" or ask_challenge_type == "docker_live_profile_challenged":
            status = "docker_live_profile_challenged"
            ok = False
        elif sentinel_completed_ok:
            status = "completed"
            ok = True
        elif ask_completed_with_expected_token and not bootstrap_completed_with_expected_token:
            status = "bootstrap_sentinel_missing_after_ask_success"
            ok = False
        elif bootstrap_ok and ask_ok:
            status = "verified"
            ok = True
        else:
            status = ask_status or "ask_failed"
            ok = False
        result = {
            "ok": ok,
            "action": "test_release_live_continuous",
            "status": status,
            "project_url": project_url,
            "conversation_url": conversation_url,
            "project_result": project_result,
            "bootstrap_result": bootstrap_result,
            "bootstrap_guardrail_retry": bootstrap_guardrail_retry,
            "bootstrap_sentinel_retry": bootstrap_sentinel_retry,
            "ask_result": ask_result,
            "continuous_browser_session": True,
            "same_profile_for_project_bootstrap_and_ask": True,
            "warmup_conversation_url": warmup_conversation_url,
            "warmup_strategy": "trusted_preflight_conversation_url" if warmup_conversation_url else "configured_project_url",
            "trusted_conversation_direct_mode": direct_conversation_mode,
            "project_identity_source": "warmup_conversation_url" if direct_conversation_mode else "project_ensure",
            "root_project_discovery_skipped": direct_conversation_mode,
            "bootstrap_completed_with_expected_sentinel": bootstrap_completed_with_expected_token,
            "ask_completed_with_expected_sentinel": ask_completed_with_expected_token,
            "contains_expected_sentinel": ask_completed_with_expected_token,
            "duration_seconds": round(time.monotonic() - started, 3),
        }
        if not ok:
            result["failed_phase"] = (
                "live_conversation_bootstrap"
                if status == "bootstrap_sentinel_missing_after_ask_success"
                else "ask_live"
            )
        return result

