    async def _try_remove_project_source_with_held_auth_ready_session(
        self,
        *,
        source_name: str,
        exact: bool,
        keep_open: bool,
    ) -> dict[str, Any] | None:
        session_key, session, match_mode = await self._compatible_held_auth_readiness_session()
        if session is None or session_key is None:
            self._log(
                "project-source-remove",
                "no held auth-readiness session available before Project Source remove; launching normal browser context",
                profile_dir=self.config.profile_dir,
                driver=self.driver_name,
                browser_channel=self.config.browser_channel or "default",
            )
            return None

        context = session.get("context")
        page = session.get("page")
        if context is None or page is None:
            await self._remove_held_auth_readiness_session(session_key, session, reason="project_source_remove_reuse_missing_context_or_page")
            return {
                "ok": False,
                "action": "project_source_remove",
                "status": "held_auth_ready_session_invalid",
                "error": "held auth-readiness session had no context/page; closed it instead of launching a competing browser context",
                "error_type": "held_auth_ready_session_invalid",
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "removed": False,
                "release_blocking": True,
            }

        try:
            state = await self._probe_auth_readiness_state(page)
            status = self._auth_readiness_status_from_state(state)
            session_status = self._auth_readiness_result_from_state(
                state,
                action="project_source_remove_preflight_held_auth_readiness_session_status",
                held_session=session,
            )
            session_status = self._attach_rate_limit_telemetry(session_status)
        except Exception as exc:
            await self._remove_held_auth_readiness_session(session_key, session, reason="project_source_remove_preflight_probe_failed")
            return {
                "ok": False,
                "action": "project_source_remove",
                "status": "held_auth_ready_session_probe_failed",
                "error": f"held auth-readiness session probe failed before Project Source remove: {type(exc).__name__}: {exc}",
                "error_type": type(exc).__name__,
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "removed": False,
                "release_blocking": True,
            }

        if not (
            status == "auth_preflight_ready"
            and bool(session_status.get("logged_in"))
            and not bool(session_status.get("challenge_detected"))
        ):
            await self._remove_held_auth_readiness_session(session_key, session, reason=f"project_source_remove_preflight_{status}")
            return {
                "ok": False,
                "action": "project_source_remove",
                "status": "held_auth_ready_session_not_ready",
                "error": "held auth-readiness session was challenged/stale before Project Source remove; closed it instead of launching a competing browser context",
                "error_type": "held_auth_ready_session_not_ready",
                "profile_dir": self.config.profile_dir,
                "held_session_reused": False,
                "held_session_closed": True,
                "held_session_status": session_status,
                "removed": False,
                "release_blocking": True,
                "recovery_hint": "Run the standard browser auth-readiness bootstrap/check again before retrying Project Source removal.",
            }

        self._log(
            "project-source-remove",
            "reusing held auth-readiness browser session for Project Source remove",
            session_key=session_key,
            match_mode=match_mode,
            profile_dir=self.config.profile_dir,
            project_url=self.config.project_url,
            source_name=source_name,
        )

        try:
            result = await self._remove_project_source_operation(
                context=context,
                page=page,
                source_name=source_name,
                exact=exact,
                keep_open=keep_open,
            )
            if isinstance(result, dict):
                result.setdefault("held_session_reused", True)
                result.setdefault("held_session_match_mode", match_mode)
                result.setdefault("held_session_key", session_key)
                result.setdefault("held_session_status", session_status)
                result = self._attach_rate_limit_telemetry(result)
            self._log("result", "Project Source remove completed via held auth-readiness session", result_type=type(result).__name__)
            return result
        except Exception as exc:
            current_url = await self._safe_page_url(page)
            self._log(
                "error",
                "Project Source remove failed while reusing held auth-readiness session",
                error_type=type(exc).__name__,
                error=str(exc),
                current_url=current_url,
                session_key=session_key,
            )
            await self._dump_failure_artifacts(page, "project_source_remove_held_session", exc)
            raise

    @property
    def driver_name(self) -> str:
        return "patchright" if self.config.use_patchright else "playwright"

    @staticmethod
    def _chrome_arg_present(args: list[str], option_name: str) -> bool:
        return any(str(arg) == option_name or str(arg).startswith(f"{option_name}=") for arg in args)

    def _headed_patchright_safe_args_enabled(self) -> bool:
        value = os.getenv("CHATGPT_PATCHRIGHT_HEADED_SAFE_ARGS", "1")
        return value.strip().lower() not in {"0", "false", "no", "off", "disabled"}

    def _effective_browser_args(self) -> list[str]:
        args = list(self.config.extra_browser_args)
        if (
            self.config.use_patchright
            and self.config.is_headed
            and self._headed_patchright_safe_args_enabled()
        ):
            # v0.0.278.63: local headed Patchright on Linux/Wayland can crash
            # before ChatGPT loads with a Vulkan/Ozone error.  Add these only
            # for headed Patchright sessions; Docker/headless remains unchanged.
            if not self._chrome_arg_present(args, "--ozone-platform"):
                args.append("--ozone-platform=x11")
            if not self._chrome_arg_present(args, "--disable-gpu"):
                args.append("--disable-gpu")
            if not self._chrome_arg_present(args, "--disable-vulkan"):
                args.append("--disable-vulkan")
        return args

    def _browser_launch_failure_payload(
        self,
        exc: Exception,
        *,
        stage: str = "launch_persistent_context",
        retry_attempted: bool = False,
        removed_singleton_artifacts: list[str] | None = None,
    ) -> dict[str, Any]:
        message = str(exc)
        lower_message = message.lower()
        likely_linux_gpu_backend = (
            "network.setcachedisabled" in lower_message
            or "connection closed while reading from the driver" in lower_message
            or "ozone-platform=wayland" in lower_message
            or "vulkan" in lower_message
        )
        return {
            "ok": False,
            "status": "browser_launch_failed",
            "error": message,
            "error_type": type(exc).__name__,
            "timeout_layer": "browser_launch",
            "browser_mode": "local_headed_patchright" if self.config.use_patchright and self.config.is_headed else self.driver_name,
            "browser_driver": self.driver_name,
            "headless": self.config.headless,
            "browser_channel": self.config.browser_channel or "default",
            "profile_dir": self.config.profile_dir,
            "stage": stage,
            "retry_attempted": bool(retry_attempted),
            "removed_singleton_artifacts": list(removed_singleton_artifacts or []),
            "browser_args": self._effective_browser_args(),
            "likely_linux_gpu_backend_issue": bool(likely_linux_gpu_backend),
            "recovery_hint": (
                "Headed Patchright failed before a browser context became usable. "
                "v0.0.278.63 applies --ozone-platform=x11 --disable-gpu --disable-vulkan by default for headed Patchright. "
                "Set CHATGPT_BROWSER_EXTRA_ARGS for additional local Chrome flags or CHATGPT_PATCHRIGHT_HEADED_SAFE_ARGS=0 to disable these defaults."
            ),
        }

    def _clear_profile_singleton_locks(self) -> list[str]:
        if not self.config.clear_singleton_locks:
            return []

        removed: list[str] = []
        profile_dir = Path(self.config.profile_dir)
        for name in ("SingletonLock", "SingletonSocket", "SingletonCookie"):
            target = profile_dir / name
            try:
                if target.is_dir() and not target.is_symlink():
                    shutil.rmtree(target)
                    removed.append(name)
                elif target.exists() or target.is_symlink():
                    target.unlink()
                    removed.append(name)
            except FileNotFoundError:
                continue
            except Exception as exc:
                self._log(
                    'driver',
                    'failed to clear profile singleton lock artifact',
                    artifact=name,
                    path=str(target),
                    error_type=type(exc).__name__,
                    error=str(exc),
                )

        if removed:
            self._log('driver', 'cleared profile singleton lock artifacts', artifacts=removed, profile_dir=self.config.profile_dir)
        return removed


    @staticmethod
    def _browser_context_launch_recoverable(exc: Exception) -> bool:
        message = str(exc)
        error_type = type(exc).__name__
        recoverable_markers = (
            "Target page, context or browser has been closed",
            "Opening in existing browser session",
            "ProcessSingleton",
            "SingletonLock",
            "SingletonSocket",
            "user data dir",
            "user data directory",
            "profile appears to be in use",
            "browser has been closed",
            "context has been closed",
        )
        return error_type == "TargetClosedError" or any(marker.lower() in message.lower() for marker in recoverable_markers)

    @staticmethod
    def _is_browser_target_closed_error(exc: Exception) -> bool:
        message = str(exc).lower()
        error_type = type(exc).__name__
        target_closed_markers = (
            "target page, context or browser has been closed",
            "page has been closed",
            "browser has been closed",
            "context has been closed",
            "target closed",
        )
        return error_type == "TargetClosedError" or any(marker in message for marker in target_closed_markers)

    @staticmethod
    def _page_reports_closed(page: Any) -> bool:
        try:
            is_closed = getattr(page, "is_closed", None)
            if callable(is_closed):
                return bool(is_closed())
        except Exception:
            return True
        return False

    async def _launch_persistent_context_with_recovery(self, chromium: Any, launch_kwargs: dict[str, Any]) -> Any:
        try:
            return await chromium.launch_persistent_context(**launch_kwargs)
        except Exception as exc:
            if not self._browser_context_launch_recoverable(exc):
                payload = self._browser_launch_failure_payload(exc, retry_attempted=False)
                raise BrowserContextUnavailableError(
                    f"browser_launch_failed: {type(exc).__name__}: {exc}",
                    payload=payload,
                ) from exc
            held_key, _held_session = await self._any_active_held_auth_readiness_session_for_profile()
            if _held_session is not None:
                payload = self._browser_launch_failure_payload(exc, retry_attempted=False)
                payload.update({
                    "status": "browser_context_unavailable_held_auth_session_active",
                    "held_auth_readiness_session_active": True,
                    "held_auth_readiness_session_key": held_key,
                    "recovery_hint": "Use the held auth-ready session or close it cleanly before launching another persistent context; singleton cleanup is unsafe while it is active.",
                })
                self._log(
                    "driver",
                    "browser persistent context launch failed while held auth-readiness session is active; refusing singleton cleanup",
                    error_type=type(exc).__name__,
                    error=str(exc),
                    session_key=held_key,
                    status="browser_context_unavailable_held_auth_session_active",
                )
                raise BrowserContextUnavailableError(
                    "browser_context_unavailable_held_auth_session_active: refusing to clear Singleton* while held auth-readiness session is active",
                    payload=payload,
                ) from exc
            removed = self._clear_profile_singleton_locks()
            self._log(
                "driver",
                "browser persistent context launch failed with recoverable profile/session state; retrying once after cleanup",
                error_type=type(exc).__name__,
                error=str(exc),
                removed_singleton_artifacts=removed,
                status="browser_context_launch_retry",
            )
            await asyncio.sleep(1.0)
            try:
                return await chromium.launch_persistent_context(**launch_kwargs)
            except Exception as retry_exc:
                payload = self._browser_launch_failure_payload(
                    retry_exc,
                    retry_attempted=True,
                    removed_singleton_artifacts=removed,
                )
                payload["original_error"] = str(exc)
                payload["original_error_type"] = type(exc).__name__
                raise BrowserContextUnavailableError(
                    "browser_context_unavailable: failed to launch persistent browser context after cleanup/retry; "
                    f"original={type(exc).__name__}: {exc}; retry={type(retry_exc).__name__}: {retry_exc}",
                    payload=payload,
                ) from retry_exc

    async def _run_with_context(self, operation_name: str, operation, **kwargs) -> Any:
        respect_history_rate_limit_cooldown = bool(kwargs.pop('respect_history_rate_limit_cooldown', True))
        Path(self.config.profile_dir).mkdir(parents=True, exist_ok=True)
        held_key, _held_session = await self._any_active_held_auth_readiness_session_for_profile()
        if _held_session is not None:
            self._log(
                'driver',
                'skipping profile singleton cleanup because held auth-readiness session is active',
                operation=operation_name,
                session_key=held_key,
                profile_dir=self.config.profile_dir,
            )
        else:
            self._clear_profile_singleton_locks()
        if respect_history_rate_limit_cooldown:
            await self._respect_rate_limit_cooldown()
        else:
            self._log('rate-limit', 'skipping persisted conversation history cooldown for non-history operation', operation=operation_name)
        await self._respect_context_spacing()
        playwright_module = await self._start_driver()
        async with playwright_module as p:
            browser_args = self._effective_browser_args()
            if self.config.disable_fedcm:
                browser_args.extend([
                    "--disable-features=FedCm,FedCmAutoReauthn,FedCmWithoutThirdPartyCookies,FedCmIdpSigninStatusEnabled,FedCmIdpSigninStatusMetrics",
                    ])
            ignore_default_args = []
            if self.config.filter_no_sandbox:
                ignore_default_args.extend(["--no-sandbox", "--disable-setuid-sandbox"])

            self._log(
                "driver",
                "launching persistent chromium context",
                disable_fedcm=self.config.disable_fedcm,
                filter_no_sandbox=self.config.filter_no_sandbox,
                no_viewport=self.config.no_viewport,
                channel=self.config.browser_channel or "default",
                running_as_root=(os.geteuid() == 0 if hasattr(os, "geteuid") else None),
                browser_args=browser_args,
                ignore_default_args=ignore_default_args,
            )
            launch_kwargs = {
                "user_data_dir": self.config.profile_dir,
                "headless": self.config.headless,
                "channel": self.config.browser_channel,
                "slow_mo": self.config.slow_mo_ms,
                "accept_downloads": True,
                "args": browser_args,
                "ignore_default_args": ignore_default_args or None,
            }
            if self.config.no_viewport is True:
                launch_kwargs["no_viewport"] = True
                launch_kwargs["screen"] = {
                    "width": self.config.viewport_width,
                    "height": self.config.viewport_height,
                }
            else:
                launch_kwargs["viewport"] = {
                    "width": self.config.viewport_width,
                    "height": self.config.viewport_height,
                }

            context = await self._launch_persistent_context_with_recovery(p.chromium, launch_kwargs)
            context.set_default_timeout(self.config.navigation_timeout_ms)
            page = context.pages[0] if context.pages else await context.new_page()
            await self._install_conversation_history_request_shield(context, operation_name=operation_name)
            self._attach_context_debug(context, page, operation_name)
            if self.config.debug and self.config.save_trace:
                self._log("trace", "starting browser trace")
                await context.tracing.start(screenshots=True, snapshots=True, sources=True)

            try:
                result = await operation(context=context, page=page, **kwargs)
                result = self._attach_rate_limit_telemetry(result)
                self._log("result", f"{operation_name} completed", result_type=type(result).__name__)
                return result
            except AuthChallengeRequiredError:
                raise
            except Exception as exc:
                await self._raise_fail_fast_midrun_challenge_if_configured(
                    page,
                    stage=f"{operation_name}-exception",
                    exc=exc,
                )
                current_url = await self._safe_page_url(page)
                self._log(
                    "error",
                    f"{operation_name} failed",
                    error_type=type(exc).__name__,
                    error=str(exc),
                    current_url=current_url,
                )
                await self._dump_failure_artifacts(page, operation_name, exc)
                raise
            finally:
                await self._finalize_context(context, operation_name)
                _PROFILE_LAST_CONTEXT_CLOSED_AT[self._profile_key] = time.monotonic()

    async def _run_login_check_operation(
        self,
        *,
        context: Any,
        page: Any,
        keep_open: bool = False,
    ) -> dict[str, Any]:
        logged_in = await self.ensure_logged_in(page, context)
        result = {
            "logged_in": logged_in,
            "profile_dir": self.config.profile_dir,
            "headless": self.config.headless,
            "url": self.config.project_url,
            "driver": self.driver_name,
            "debug": self.config.debug,
            "debug_artifact_dir": self.config.debug_artifact_dir,
        }
        self._log("login-check", "login result", **result)
        if keep_open and self.config.is_headed:
            await self._pause_for_keep_open("Login check passed. Press Enter to close the browser... ")
        return result

    async def _run_passive_auth_readiness_operation(
        self,
        *,
        context: Any,
        page: Any,
        keep_open: bool = False,
    ) -> dict[str, Any]:
        await self._goto(
            page,
            self.config.project_url,
            label="passive-auth-readiness",
            respect_history_rate_limit_cooldown=False,
        )
        await self._wait_for_challenge_resolution(page, label="passive-auth-readiness")
        state = await self._probe_auth_readiness_state(page)
        result = self._auth_readiness_result_from_state(state)
        result = await self._capture_auth_readiness_observation_artifacts(page, result)
        self._log("auth-readiness", "passive auth readiness result", **result)
        if keep_open and self.config.is_headed:
            self._log("debug", "stdin keep-open is deprecated for passive auth-readiness; use service-side held session mode instead")
        return result

    async def _run_passive_auth_readiness_keep_open(self) -> dict[str, Any]:
        operation_name = "auth_readiness"
        key = self._auth_readiness_session_key()
        async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
            old_session = _AUTH_READINESS_HELD_SESSIONS.pop(key, None)
        if old_session is not None:
            await self._close_auth_readiness_held_session(old_session, reason="replaced")

        playwright = context = page = None
        try:
            playwright, context, page = await self._build_auth_readiness_launch_session(operation_name=operation_name)
            await self._goto(
                page,
                self.config.project_url,
                label="passive-auth-readiness",
                respect_history_rate_limit_cooldown=False,
            )
            await self._wait_for_challenge_resolution(page, label="passive-auth-readiness")
            state = await self._probe_auth_readiness_state(page)
            ttl_seconds = self._auth_readiness_keep_open_seconds()
            now = time.monotonic()
            session = {
                "session_key": key,
                "operation_name": operation_name,
                "playwright": playwright,
                "context": context,
                "page": page,
                "created_at_monotonic": now,
                "expires_at_monotonic": now + ttl_seconds,
                "ttl_seconds": ttl_seconds,
                "closed": False,
            }
            session["close_task"] = asyncio.create_task(self._expire_auth_readiness_session_after(key, session, ttl_seconds))
            async with _AUTH_READINESS_HELD_SESSIONS_LOCK:
                _AUTH_READINESS_HELD_SESSIONS[key] = session
            result = self._auth_readiness_result_from_state(state, held_session=session)
            result = await self._capture_auth_readiness_observation_artifacts(page, result)
            result = self._attach_rate_limit_telemetry(result)
            self._log("auth-readiness", "passive auth readiness result; browser context held", **result)
            return result
        except Exception:
            if context is not None:
                try:
                    await self._finalize_context(context, operation_name)
                except Exception:
                    pass
            if playwright is not None:
                try:
                    await playwright.stop()
                except Exception:
                    pass
            raise

    @staticmethod
    def _coerce_chat_attachment_paths(
        *,
        file_path: Optional[str] = None,
        attachment_paths: Optional[list[str]] = None,
    ) -> list[str]:
        paths: list[str] = []
        if file_path:
            paths.append(file_path)
        for attachment_path in attachment_paths or []:
            if attachment_path:
                paths.append(attachment_path)
        return paths

    async def _conversation_turn_presence_state(self, page: Any, *, prompt: str | None = None) -> dict[str, Any]:
        """Return a compact DOM hydration signal for the active conversation.

        This intentionally reuses the existing broad user/generic probes. For
        a selected existing conversation, either role-specific user turns or
        generic conversation-turn nodes are enough to prove the transcript has
        hydrated before we submit a protocol ask.
        """

        state = await self._capture_user_turn_state(page, prompt=prompt)
        generic = state.get("generic_turns") if isinstance(state.get("generic_turns"), dict) else {}
        user_count = int(state.get("count") or 0)
        generic_count = int(generic.get("count") or 0)
        return {
            "user_turn_count": user_count,
            "generic_turn_count": generic_count,
            "hydrated": bool(user_count > 0 or generic_count > 0),
            "state": state,
        }

    async def _wait_for_conversation_hydration_phase(
        self,
        page: Any,
        *,
        phase: str,
        attempts: list[dict[str, Any]],
        timeout_ms: int,
        poll_interval_ms: int,
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        """Wait for visible conversation turns during one hydration phase.

        Returns ``(presence, last_presence)``. ``presence`` is populated only
        when hydration succeeds. ``last_presence`` is always the final sampled
        state, so callers can report useful fail-closed diagnostics.
        """

        deadline = asyncio.get_running_loop().time() + (timeout_ms / 1000)
        phase_attempt = 0
        last_presence: dict[str, Any] = {}
        while True:
            phase_attempt += 1
            presence = await self._conversation_turn_presence_state(page)
            last_presence = presence
            attempts.append({
                "attempt": len(attempts) + 1,
                "phase": phase,
                "phase_attempt": phase_attempt,
                "user_turn_count": presence.get("user_turn_count"),
                "generic_turn_count": presence.get("generic_turn_count"),
                "hydrated": presence.get("hydrated"),
            })
            if presence.get("hydrated"):
                return presence, last_presence
            remaining = deadline - asyncio.get_running_loop().time()
            if remaining <= 0:
                return None, last_presence
            await page.wait_for_timeout(min(poll_interval_ms, int(max(1, remaining * 1000))))

    async def _post_reload_hydration_settle(self, page: Any, *, label: str, timeout_ms: int) -> None:
        """Give ChatGPT a chance to materialize the target conversation after reload."""

        try:
            if hasattr(page, "wait_for_load_state"):
                await page.wait_for_load_state("domcontentloaded", timeout=min(max(timeout_ms, 1_000), 10_000))
        except Exception as exc:
            self._log("hydration", "domcontentloaded settle after reload failed", label=label, error=str(exc))
        try:
            if hasattr(page, "wait_for_load_state"):
                await page.wait_for_load_state("networkidle", timeout=min(max(timeout_ms, 1_000), 10_000))
        except Exception as exc:
            self._log("hydration", "networkidle settle after reload skipped or failed", label=label, error=str(exc))
        await self._wait_for_rate_limit_modal_to_clear(page, label=label, timeout_ms=min(self.config.rate_limit_modal_wait_timeout_ms, 10_000))

    async def _ensure_target_conversation_hydrated(
        self,
        page: Any,
        *,
        target_url: str,
        label: str,
        timeout_ms: int = 20_000,
        poll_interval_ms: int = 500,
        max_reload_attempts: int = 2,
        navigation_evidence: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Block unsafe submits, but reuse an already-warm target task.

        v0.0.278.16 adds a warm-task bypass for the dominant old-chat cost:
        when the browser is already on the target conversation and the composer
        is usable, do not force full historical transcript hydration. If that
        cheap proof fails, fall back to the older fail-closed turn-hydration path.
        """

        decomposition: dict[str, Any] = {
            "hydration_mode": "not_required",
            "hydration_reuse_candidate": False,
            "hydration_reuse_used": False,
            "hydration_current_url_check_seconds": 0.0,
            "hydration_navigation_seconds": 0.0,
            "hydration_load_state_seconds": 0.0,
            "hydration_composer_ready_seconds": 0.0,
            "hydration_conversation_surface_seconds": 0.0,
            "hydration_sidebar_or_project_probe_seconds": 0.0,
            "hydration_fallback_used": False,
            "hydration_fallback_reason": None,
        }

        if not self._is_conversation_url(target_url):
            return {"status": "not_required", "target_url": target_url, "label": label, **decomposition}

        current_check_started = time.monotonic()
        current_url = await self._safe_page_url(page)
        current_norm = self._normalize_navigation_url(current_url)
        target_norm = self._normalize_navigation_url(target_url)
        same_target_conversation = bool(current_norm and target_norm and current_norm == target_norm)
        decomposition["hydration_current_url_check_seconds"] = round(time.monotonic() - current_check_started, 3)
        decomposition["hydration_reuse_candidate"] = same_target_conversation
        decomposition["hydration_navigation_skipped"] = bool(
            isinstance(navigation_evidence, dict) and navigation_evidence.get("skipped")
        )
        decomposition["hydration_navigation_mode"] = (
            navigation_evidence.get("mode") if isinstance(navigation_evidence, dict) else None
        )

        if same_target_conversation and self._warm_task_hydration_reuse_enabled():
            composer_started = time.monotonic()
            composer_ready = await self._has_chat_input(page)
            decomposition["hydration_composer_ready_seconds"] = round(time.monotonic() - composer_started, 3)
            if composer_ready:
                result = {
                    "status": "target_conversation_hydrated_warm_task_reuse",
                    "target_url": target_url,
                    "current_url": current_url,
                    "label": label,
                    "attempt_count": 0,
                    "reload_performed": False,
                    "reload_count": 0,
                    "timeout_ms": timeout_ms,
                    "poll_interval_ms": poll_interval_ms,
                    "attempts": [],
                    "state": None,
                    **decomposition,
                }
                result["hydration_mode"] = "warm_task_reuse"
                result["hydration_reuse_used"] = True
                self._log(
                    "hydration",
                    "warm target conversation reused without full transcript hydration",
                    **{k: v for k, v in result.items() if k != "state"},
                )
                return result
            decomposition["hydration_fallback_used"] = True
            decomposition["hydration_fallback_reason"] = "composer_not_ready_for_warm_task_reuse"
        elif same_target_conversation:
            decomposition["hydration_fallback_used"] = True
            decomposition["hydration_fallback_reason"] = "warm_task_reuse_disabled"
        else:
            decomposition["hydration_fallback_used"] = True
            decomposition["hydration_fallback_reason"] = "current_url_not_target_conversation"

        attempts: list[dict[str, Any]] = []
        reload_count = 0
        last_presence: dict[str, Any] = {}

        surface_started = time.monotonic()
        presence, last_presence = await self._wait_for_conversation_hydration_phase(
            page,
            phase="initial_wait",
            attempts=attempts,
            timeout_ms=timeout_ms,
            poll_interval_ms=poll_interval_ms,
        )
        decomposition["hydration_conversation_surface_seconds"] = round(
            decomposition.get("hydration_conversation_surface_seconds", 0.0) + (time.monotonic() - surface_started),
            3,
        )
        if presence is not None:
            result = {
                "status": "target_conversation_hydrated",
                "target_url": target_url,
                "current_url": current_url,
                "label": label,
                "attempt_count": len(attempts),
                "reload_performed": False,
                "reload_count": reload_count,
                "timeout_ms": timeout_ms,
                "poll_interval_ms": poll_interval_ms,
                "attempts": attempts,
                "state": presence.get("state"),
                **decomposition,
            }
            result["hydration_mode"] = "conversation_turns"
            self._log("hydration", "target conversation hydrated before submit", **{k: v for k, v in result.items() if k != "state"})
            return result

        for reload_index in range(max(0, int(max_reload_attempts))):
            reload_count += 1
            phase = f"after_reload_{reload_count}"
            self._log(
                "hydration",
                "target conversation not hydrated; forcing bounded reload before submit",
                target_url=target_url,
                label=label,
                reload_count=reload_count,
                max_reload_attempts=max_reload_attempts,
                previous_attempts=attempts,
            )
            navigation_started = time.monotonic()
            await page.goto(target_url, wait_until="domcontentloaded")
            decomposition["hydration_navigation_seconds"] = round(
                decomposition.get("hydration_navigation_seconds", 0.0) + (time.monotonic() - navigation_started),
                3,
            )
            load_started = time.monotonic()
            await self._post_reload_hydration_settle(page, label=f"{label}-hydration-reload-{reload_count}", timeout_ms=timeout_ms)
            decomposition["hydration_load_state_seconds"] = round(
                decomposition.get("hydration_load_state_seconds", 0.0) + (time.monotonic() - load_started),
                3,
            )
            surface_started = time.monotonic()
            presence, last_presence = await self._wait_for_conversation_hydration_phase(
                page,
                phase=phase,
                attempts=attempts,
                timeout_ms=timeout_ms,
                poll_interval_ms=poll_interval_ms,
            )
            decomposition["hydration_conversation_surface_seconds"] = round(
                decomposition.get("hydration_conversation_surface_seconds", 0.0) + (time.monotonic() - surface_started),
                3,
            )
            if presence is not None:
                result = {
                    "status": "target_conversation_hydrated_after_reload",
                    "target_url": target_url,
                    "current_url": current_url,
                    "label": label,
                    "attempt_count": len(attempts),
                    "reload_performed": True,
                    "reload_count": reload_count,
                    "timeout_ms": timeout_ms,
                    "poll_interval_ms": poll_interval_ms,
                    "attempts": attempts,
                    "state": presence.get("state"),
                    **decomposition,
                }
                result["hydration_mode"] = "reload_then_conversation_turns"
                self._log("hydration", "target conversation hydrated after bounded reload", **{k: v for k, v in result.items() if k != "state"})
                return result

        state = last_presence.get("state") if isinstance(last_presence, dict) else None
        result = {
            "status": "target_conversation_not_hydrated_before_submit",
            "target_url": target_url,
            "current_url": current_url,
            "label": label,
            "attempt_count": len(attempts),
            "reload_performed": reload_count > 0,
            "reload_count": reload_count,
            "max_reload_attempts": max_reload_attempts,
            "timeout_ms": timeout_ms,
            "poll_interval_ms": poll_interval_ms,
            "final_user_turn_count": last_presence.get("user_turn_count") if isinstance(last_presence, dict) else None,
            "final_generic_turn_count": last_presence.get("generic_turn_count") if isinstance(last_presence, dict) else None,
            "attempts": attempts,
            "state": state,
            **decomposition,
        }
        result["hydration_mode"] = "failed_conversation_turns"
        self._log("hydration", "target conversation not hydrated before submit; refusing to submit", **{k: v for k, v in result.items() if k != "state"})
        return result

    async def _upload_chat_attachments(self, page: Any, file_paths: list[str]) -> None:
        normalized_paths = [str(Path(path)) for path in file_paths]
        for path in normalized_paths:
            if not os.path.exists(path):
                raise FileNotFoundError(path)
        self._log("upload", "upload requested", file_paths=normalized_paths, attachment_count=len(normalized_paths))
        file_input = page.locator('input[type="file"]')
        file_count = await file_input.count()
        self._log("upload", "file input selector count", selector='input[type="file"]', count=file_count)
        if not file_count:
            raise ResponseTimeoutError("File upload input was not found")
        payload: Any = normalized_paths[0] if len(normalized_paths) == 1 else normalized_paths
        try:
            await file_input.first.set_input_files(payload)
        except Exception as exc:
            if len(normalized_paths) <= 1:
                raise
            self._log("upload", "multi-file upload failed; retrying single files", error=str(exc), attachment_count=len(normalized_paths))
            for path in normalized_paths:
                await file_input.first.set_input_files(path)
        self._log("upload", "file uploaded to browser input", file_paths=normalized_paths, attachment_count=len(normalized_paths))

    async def _capture_attachment_visible_state(
        self,
        page: Any,
        *,
        expected_filenames: list[str],
    ) -> dict[str, Any]:
        """Capture best-effort attachment-chip visibility diagnostics.

        This is diagnostic-only: it must not change submit behavior.  ChatGPT's
        attachment DOM is not a stable public API, so we collect both exact
        filename matches and coarse visible attachment/file element evidence.
        """

        expected = [str(name) for name in expected_filenames if str(name).strip()]
        if not expected:
            return {
                "status": "no_expected_attachment_filename",
                "visible": False,
                "filename_expected": None,
                "filename_visible": None,
                "exact_filename_match": False,
            }
        try:
            state = await page.evaluate(
                """
                (expected) => {
                  const isVisible = (el) => {
                    if (!el) return false;
                    const style = window.getComputedStyle(el);
                    if (!style || style.visibility === 'hidden' || style.display === 'none') return false;
                    const rect = el.getBoundingClientRect();
                    return rect.width > 0 && rect.height > 0;
                  };
                  const selectors = [
                    '[data-testid*=\"attachment\" i]',
                    '[data-testid*=\"file\" i]',
                    '[aria-label*=\"attachment\" i]',
                    '[aria-label*=\"file\" i]',
                    '[class*=\"attachment\" i]',
                    '[class*=\"file\" i]',
                    'button',
                    'span',
                    'div'
                  ];
                  const nodes = [];
                  const seen = new Set();
                  for (const selector of selectors) {
                    for (const el of Array.from(document.querySelectorAll(selector))) {
                      if (seen.has(el) || !isVisible(el)) continue;
                      seen.add(el);
                      const text = (el.innerText || el.textContent || '').trim();
                      const aria = (el.getAttribute('aria-label') || '').trim();
                      const title = (el.getAttribute('title') || '').trim();
                      const testid = (el.getAttribute('data-testid') || '').trim();
                      const combined = [text, aria, title, testid].filter(Boolean).join(' | ');
                      if (!combined) continue;
                      const matches = expected.filter(name => combined.includes(name));
                      const looksFileLike = /attach|attachment|file|document|upload/i.test(combined);
                      if (matches.length || looksFileLike) {
                        nodes.push({
                          tag: el.tagName,
                          text: text.slice(0, 240),
                          aria_label: aria.slice(0, 240),
                          title: title.slice(0, 240),
                          data_testid: testid.slice(0, 120),
                          matched_filenames: matches
                        });
                      }
                    }
                    if (nodes.length >= 20) break;
                  }
                  const bodyText = ((document.body && (document.body.innerText || document.body.textContent)) || '').slice(0, 200000);
                  const bodyMatches = expected.filter(name => bodyText.includes(name));
                  const nodeMatches = [];
                  for (const node of nodes) {
                    for (const name of node.matched_filenames || []) {
                      if (!nodeMatches.includes(name)) nodeMatches.push(name);
                    }
                  }
                  const matches = Array.from(new Set([...bodyMatches, ...nodeMatches]));
                  return {
                    status: matches.length ? 'attachment_filename_visible' : (nodes.length ? 'attachment_chip_visible_without_exact_filename' : 'attachment_chip_not_visible'),
                    visible: matches.length > 0 || nodes.length > 0,
                    filename_expected: expected[0] || null,
                    filename_visible: matches[0] || null,
                    exact_filename_match: matches.length > 0,
                    visible_candidate_count: nodes.length,
                    visible_candidates: nodes.slice(0, 8)
                  };
                }
                """,
                expected,
            )
            if isinstance(state, dict):
                return state
        except Exception as exc:  # pragma: no cover - browser diagnostics only
            return {
                "status": "attachment_visibility_probe_failed",
                "visible": False,
                "filename_expected": expected[0],
                "filename_visible": None,
                "exact_filename_match": False,
                "error": str(exc),
            }
        return {
            "status": "attachment_visibility_probe_invalid_result",
            "visible": False,
            "filename_expected": expected[0],
            "filename_visible": None,
            "exact_filename_match": False,
        }

    async def _wait_for_attachment_submit_ready(
        self,
        page: Any,
        *,
        timeout_ms: int = 15_000,
        poll_interval_ms: int = 250,
    ) -> dict[str, Any]:
        """Wait for ChatGPT to finish attachment ingestion enough to enable Send.

        File uploads can put the composer through a transient processing state in
        which Enter is accepted by the focused editor but does not create a
        conversation.  For attachment asks, require the real send button to be
        visible/enabled before dispatching submit.
        """

        started = time.monotonic()
        deadline = asyncio.get_running_loop().time() + max(0.1, timeout_ms / 1000.0)
        attempts: list[dict[str, Any]] = []
        last_state: dict[str, Any] = {}
        while asyncio.get_running_loop().time() < deadline:
            state = await self._probe_submit_button_state(page)
            last_state = state if isinstance(state, dict) else {}
            attempt = {
                "elapsed_seconds": round(time.monotonic() - started, 3),
                "send_ready": bool(last_state.get("send_ready")),
                "stop_visible": bool(last_state.get("stop_visible")),
                "idle_visible": bool(last_state.get("idle_visible")),
                "selector": last_state.get("selector"),
                "aria_label": last_state.get("aria_label"),
                "data_testid": last_state.get("data_testid"),
                "visible": last_state.get("visible"),
                "enabled": last_state.get("enabled"),
            }
            if len(attempts) < 20:
                attempts.append(attempt)
            if attempt["send_ready"] and not attempt["stop_visible"]:
                result = {
                    "status": "attachment_submit_ready",
                    "ready": True,
                    "duration_seconds": round(time.monotonic() - started, 3),
                    "attempt_count": len(attempts),
                    "last_state": last_state,
                    "attempts": attempts,
                }
                self._log("upload", "attachment submit ready", **{k: v for k, v in result.items() if k != "attempts"})
                return result
            await page.wait_for_timeout(poll_interval_ms)

        result = {
            "status": "attachment_submit_ready_timeout",
            "ready": False,
            "duration_seconds": round(time.monotonic() - started, 3),
            "attempt_count": len(attempts),
            "last_state": last_state,
            "attempts": attempts,
        }
        self._log("upload", "attachment submit readiness timed out", **{k: v for k, v in result.items() if k != "attempts"})
        return result

    async def _ask_question_operation(
        self,
        *,
        context: Any,
        page: Any,
        prompt: str,
        file_path: Optional[str],
        attachment_paths: Optional[list[str]] = None,
        conversation_url: str | None = None,
        expect_json: bool,
        keep_open: bool = False,
        service_timeout_seconds: Optional[float] = None,
        prefer_button_submit: bool = False,
        reuse_current_page_if_ready: bool = False,
    ) -> dict[str, Any]:
        operation_started = time.monotonic()
        ask_operation_deadline_monotonic = self._ask_operation_deadline_monotonic(
            operation_started=operation_started,
            service_timeout_seconds=service_timeout_seconds,
        )
        phase_timings: dict[str, Any] = {
            "submit_method": None,
            "slow_phase_warnings": [],
            "service_timeout_seconds": float(service_timeout_seconds) if service_timeout_seconds is not None else None,
            "prefer_button_submit": bool(prefer_button_submit),
            "ask_operation_deadline_reserve_ms": self._ask_operation_deadline_reserve_ms(),
            "ask_operation_deadline_monotonic": ask_operation_deadline_monotonic,
        }

        def mark_phase(name: str, started: float) -> None:
            phase_timings[name] = round(time.monotonic() - started, 3)

        prompt, response_request_binding = self._prepare_json_response_request_binding(
            prompt,
            expect_json=expect_json,
        )
        phase_timings["response_request_binding_required"] = response_request_binding.get("response_request_binding_required")
        phase_timings["response_request_binding_mode"] = response_request_binding.get("response_request_binding_mode")
        phase_timings["response_request_marker_count"] = response_request_binding.get("response_request_marker_count")
        phase_timings["response_request_nonce_injected"] = response_request_binding.get("response_request_nonce_injected")

        target_url = conversation_url or self.config.project_url
        requested_target_url = target_url
        using_held_current_page = False
        held_current_page_status: dict[str, Any] | None = None
        held_scope_evidence: dict[str, Any] | None = None
        project_scope_navigation_check_required = False

        async def browser_lifetime_failure_result(*, submit_phase: str, exc: Exception | None = None) -> dict[str, Any]:
            phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
            phase_timings["browser_lifetime_submit_phase"] = submit_phase
            phase_timings["browser_context_closed_during_submit"] = True
            phase_timings["submit_subphase"] = submit_phase
            current_url = await self._safe_page_url(page)
            result = {
                "ok": False,
                "action": "ask",
                "status": "browser_context_closed_during_submit",
                "error": "browser/page context closed after readiness and before or during composer submit",
                "error_type": "browser_context_closed_during_submit",
                "failed_phase": "submit",
                "submit_failure_phase": submit_phase,
                "submit_subphase": submit_phase,
                "current_url": current_url,
                "requested_target_url": requested_target_url,
                "conversation_url": target_url if self._is_conversation_url(target_url) else None,
                "partial_result": True,
                "release_blocking": True,
                "challenge_evidence_present": False,
                "ask_phase_timings": phase_timings,
            }
            if exc is not None:
                result["exception_type"] = type(exc).__name__
                result["exception_text"] = str(exc)[:800]
            self._record_ask_progress(**result)
            self._log(
                "submit",
                "browser/page context closed during composer submit; returning structured live browser lifetime failure",
                submit_failure_phase=submit_phase,
                current_url=current_url,
                error_type=type(exc).__name__ if exc is not None else None,
                error=str(exc)[:240] if exc is not None else None,
            )
            return result

        phase_started = time.monotonic()
        if reuse_current_page_if_ready:
            held_state = await self._probe_auth_readiness_state(page)
            held_status = self._auth_readiness_status_from_state(held_state)
            held_current_page_status = self._auth_readiness_result_from_state(
                held_state,
                action="ask_held_auth_ready_current_page_status",
                held_session=None,
            )
            if (
                held_status == "auth_preflight_ready"
                and bool(held_current_page_status.get("composer_visible"))
                and bool(held_current_page_status.get("logged_in"))
                and not bool(held_current_page_status.get("challenge_detected"))
            ):
                current_url = held_current_page_status.get("current_url") or await self._safe_page_url(page)
                held_scope_evidence = self._ask_target_scope_evidence(
                    current_url=str(current_url or ''),
                    target_url=str(requested_target_url or ''),
                )
                if held_scope_evidence.get("matches") is True:
                    if isinstance(current_url, str) and current_url.strip():
                        target_url = current_url.strip()
                    using_held_current_page = True
                    self._log(
                        "ask",
                        "using held auth-ready current page for ask; skipping target navigation",
                        current_url=target_url,
                        requested_target_url=requested_target_url,
                        composer_visible=held_current_page_status.get("composer_visible"),
                        logged_in=held_current_page_status.get("logged_in"),
                        scope_reason=held_scope_evidence.get("reason"),
                    )
                else:
                    project_scope_navigation_check_required = bool(held_scope_evidence.get("target_project_scoped"))
                    self._log(
                        "ask",
                        "held auth-ready current page is outside requested target scope; navigating within held session",
                        current_url=current_url,
                        requested_target_url=requested_target_url,
                        scope_reason=held_scope_evidence.get("reason"),
                        target_project_scoped=held_scope_evidence.get("target_project_scoped"),
                        target_conversation_id=held_scope_evidence.get("target_conversation_id"),
                        current_conversation_id=held_scope_evidence.get("current_conversation_id"),
                    )
            else:
                phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
                result = {
                    "ok": False,
                    "action": "ask",
                    "status": "held_auth_ready_current_page_not_ready",
                    "error": "held auth-ready session was not ready at send time; refusing to navigate to a Cloudflare-prone target URL",
                    "error_type": "held_auth_ready_current_page_not_ready",
                    "requested_target_url": requested_target_url,
                    "held_current_page_status": held_current_page_status,
                    "partial_result": True,
                    "release_blocking": True,
                    "ask_phase_timings": phase_timings,
                }
                self._record_ask_progress(**result)
                return result
        else:
            await self.ensure_logged_in(page, context)
        mark_phase("auth_check_seconds", phase_started)

        phase_started = time.monotonic()
        if using_held_current_page:
            navigation_evidence = {
                "mode": "held_auth_ready_current_page",
                "skipped": True,
                "refresh_required": False,
                "reason": "held_auth_ready_current_page_matches_requested_scope",
                "scope_reason": held_scope_evidence.get("reason") if isinstance(held_scope_evidence, dict) else None,
                "requested_target_url": requested_target_url,
                "current_url": target_url,
            }
        else:
            navigation_evidence = await self._goto(page, target_url, label="chat-home-after-login")
        mark_phase("navigation_seconds", phase_started)
        if isinstance(navigation_evidence, dict):
            phase_timings["navigation_mode"] = navigation_evidence.get("mode")
            phase_timings["navigation_skipped"] = navigation_evidence.get("skipped")
            phase_timings["navigation_refresh_required"] = navigation_evidence.get("refresh_required")
            phase_timings["navigation_reason"] = navigation_evidence.get("reason")
            phase_timings["navigation_scope_reason"] = navigation_evidence.get("scope_reason")
            phase_timings["requested_target_url"] = navigation_evidence.get("requested_target_url")
            phase_timings["effective_target_url"] = navigation_evidence.get("current_url") or target_url
        phase_timings["held_auth_ready_current_page_used"] = bool(using_held_current_page)
        if held_current_page_status is not None:
            phase_timings["held_current_page_status"] = held_current_page_status.get("status")
        if held_scope_evidence is not None:
            phase_timings["held_scope_match"] = held_scope_evidence.get("matches")
            phase_timings["held_scope_reason"] = held_scope_evidence.get("reason")
            phase_timings["held_scope_target_project_scoped"] = held_scope_evidence.get("target_project_scoped")
            phase_timings["held_scope_target_conversation_id"] = held_scope_evidence.get("target_conversation_id")
            phase_timings["held_scope_current_conversation_id"] = held_scope_evidence.get("current_conversation_id")

        if project_scope_navigation_check_required:
            post_nav_state = await self._probe_auth_readiness_state(page)
            post_nav_status = self._auth_readiness_status_from_state(post_nav_state)
            post_nav_result = self._auth_readiness_result_from_state(
                post_nav_state,
                action="ask_project_scope_post_navigation_status",
                held_session=None,
            )
            phase_timings["project_scope_post_navigation_status"] = post_nav_status
            phase_timings["project_scope_post_navigation_url"] = post_nav_result.get("current_url")
            if bool(post_nav_result.get("challenge_detected")) or post_nav_status.startswith("auth_challenge"):
                phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
                result = {
                    "ok": False,
                    "action": "ask",
                    "status": "project_scope_navigation_challenged",
                    "error": "navigating the held auth-ready session to the requested project scope triggered a Cloudflare challenge; refusing to submit outside the project",
                    "error_type": "project_scope_navigation_challenged",
                    "requested_target_url": requested_target_url,
                    "current_url": post_nav_result.get("current_url"),
                    "held_scope_evidence": held_scope_evidence,
                    "post_navigation_status": post_nav_result,
                    "partial_result": True,
                    "release_blocking": True,
                    "recovery_hint": "Run Docker browser bootstrap against the current project conversation/home URL, then retry pb ask.",
                    "ask_phase_timings": phase_timings,
                }
                self._record_ask_progress(**result)
                return result
            post_scope = self._ask_target_scope_evidence(
                current_url=str(post_nav_result.get("current_url") or await self._safe_page_url(page)),
                target_url=str(requested_target_url or ''),
            )
            phase_timings["project_scope_post_navigation_match"] = post_scope.get("matches")
            phase_timings["project_scope_post_navigation_reason"] = post_scope.get("reason")
            if post_scope.get("matches") is not True:
                phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
                result = {
                    "ok": False,
                    "action": "ask",
                    "status": "project_scope_navigation_mismatch",
                    "error": "navigation completed without challenge but did not land in the requested project/conversation scope; refusing to submit",
                    "error_type": "project_scope_navigation_mismatch",
                    "requested_target_url": requested_target_url,
                    "current_url": post_nav_result.get("current_url"),
                    "held_scope_evidence": held_scope_evidence,
                    "post_navigation_scope_evidence": post_scope,
                    "post_navigation_status": post_nav_result,
                    "partial_result": True,
                    "release_blocking": True,
                    "ask_phase_timings": phase_timings,
                }
                self._record_ask_progress(**result)
                return result

        phase_started = time.monotonic()
        hydration = await self._ensure_target_conversation_hydrated(
            page,
            target_url=target_url,
            label="chat-home-after-login",
            navigation_evidence=navigation_evidence if isinstance(navigation_evidence, dict) else None,
        )
        mark_phase("hydration_seconds", phase_started)
        if isinstance(hydration, dict):
            for hydration_key in [
                "hydration_mode",
                "hydration_reuse_candidate",
                "hydration_reuse_used",
                "hydration_current_url_check_seconds",
                "hydration_navigation_seconds",
                "hydration_load_state_seconds",
                "hydration_composer_ready_seconds",
                "hydration_conversation_surface_seconds",
                "hydration_sidebar_or_project_probe_seconds",
                "hydration_fallback_used",
                "hydration_fallback_reason",
                "hydration_navigation_skipped",
                "hydration_navigation_mode",
            ]:
                phase_timings[hydration_key] = hydration.get(hydration_key)
        if isinstance(hydration, dict) and hydration.get("status") == "target_conversation_not_hydrated_before_submit":
            phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
            return {
                "ok": False,
                "status": "target_conversation_not_hydrated_before_submit",
                "error": "target_conversation_not_hydrated_before_submit: target conversation URL loaded but no conversation turns hydrated before submit",
                "error_type": "target_conversation_not_hydrated_before_submit",
                "conversation_url": target_url if self._is_conversation_url(target_url) else None,
                "hydration_evidence": hydration,
                "partial_result": True,
                "ask_phase_timings": phase_timings,
            }

        phase_started = time.monotonic()
        try:
            input_locator = await self._wait_for_chat_input(page)
        except Exception as exc:
            if self._is_browser_target_closed_error(exc):
                mark_phase("input_wait_seconds", phase_started)
                return await browser_lifetime_failure_result(submit_phase="composer_wait", exc=exc)
            raise
        mark_phase("input_wait_seconds", phase_started)

        phase_started = time.monotonic()
        await self._wait_for_rate_limit_modal_to_clear(page, label="ask-question-before-composer-click")
        mark_phase("rate_limit_wait_seconds", phase_started)

        phase_started = time.monotonic()
        composer_ready_evidence = await self._wait_for_composer_ready_before_fill(page)
        mark_phase("composer_ready_before_fill_seconds", phase_started)
        phase_timings["composer_ready_before_fill_status"] = composer_ready_evidence.get("status")
        phase_timings["composer_ready_before_fill_blockers"] = composer_ready_evidence.get("blockers")
        phase_timings["composer_ready_before_fill_send_ready"] = composer_ready_evidence.get("send_ready")
        phase_timings["composer_ready_before_fill_stop_visible"] = composer_ready_evidence.get("stop_visible")
        if composer_ready_evidence.get("status") != "composer_ready":
            phase_timings["total_seconds"] = round(time.monotonic() - operation_started, 3)
            blockers = set(composer_ready_evidence.get("blockers") or [])
            busy_blockers = {"stop_button_visible", "thinking_visible", "interrupted_answer_state"}
            target_conversation_busy = bool(self._is_conversation_url(target_url) and blockers.intersection(busy_blockers))
            status = "target_conversation_busy" if target_conversation_busy else "composer_not_ready_before_fill"
            error = (
                "target conversation is busy; refusing to type into a running or interrupted composer"
                if target_conversation_busy
                else "composer was not ready before fill; refusing to type into a running or interrupted composer"
            )
            result = {
                "ok": False,
                "action": "ask",
                "status": status,
                "error": error,
                "error_type": status,
                "timeout_layer": "composer_ready_before_fill",
                "conversation_url": target_url if self._is_conversation_url(target_url) else None,
                "composer_ready_evidence": composer_ready_evidence,
                "partial_result": True,
                "ask_phase_timings": phase_timings,
            }
            if target_conversation_busy:
                result["recovery_hint"] = "Wait for the current conversation to finish, stop it manually, or rerun with --new-task."
            self._record_ask_progress(**result)
            return result

        await self._debug_pause_if_enabled(
            label="before_fill",
            enabled=bool(getattr(self.config, "pause_before_fill", False)),
            prompt="Debug pause before filling the composer. Inspect the browser, then press Enter to continue... ",
        )

        if self._page_reports_closed(page):
            return await browser_lifetime_failure_result(submit_phase="pre_composer_click_closed")

        self._log("composer", "chat input resolved and composer ready; clicking")
        phase_started = time.monotonic()
        try:
            await self._click_locator_with_fallback(input_locator, label="ask-question-composer-input", timeout_ms=5_000)
        except Exception as exc:
            if self._is_browser_target_closed_error(exc):
                mark_phase("composer_click_seconds", phase_started)
                return await browser_lifetime_failure_result(submit_phase="composer_click", exc=exc)
            raise
        mark_phase("composer_click_seconds", phase_started)

        if self._page_reports_closed(page):
            return await browser_lifetime_failure_result(submit_phase="pre_prompt_fill_closed")

        phase_started = time.monotonic()
        try:
            fill_evidence = await self._fill_chat_prompt(page, input_locator, prompt=prompt)
        except Exception as exc:
            if self._is_browser_target_closed_error(exc):
                mark_phase("prompt_fill_seconds", phase_started)
                return await browser_lifetime_failure_result(submit_phase="prompt_fill", exc=exc)
            raise
        mark_phase("prompt_fill_seconds", phase_started)
        phase_timings["prompt_fill_method"] = fill_evidence.get("method")
        phase_timings["prompt_fill_requested_method"] = fill_evidence.get("requested_method")
        phase_timings["prompt_fill_fallback_used"] = bool(fill_evidence.get("fallback_used"))
        phase_timings["prompt_fill_trusted_input_used"] = bool(fill_evidence.get("trusted_input_used"))
        phase_timings["prompt_fill_trusted_paste_used"] = bool(fill_evidence.get("trusted_paste_used"))
        phase_timings["prompt_fill_keyboard_insert_used"] = bool(fill_evidence.get("keyboard_insert_used"))
        phase_timings["prompt_fill_locator_fill_used"] = bool(fill_evidence.get("locator_fill_used"))
        phase_timings["prompt_fill_verification_passed"] = bool(fill_evidence.get("verification_passed"))
        phase_timings["prompt_fill_react_state_probe"] = fill_evidence.get("react_state_probe")

        await self._debug_pause_if_enabled(
            label="after_fill",
            enabled=bool(getattr(self.config, "pause_after_fill", False)),
            prompt="Debug pause after filling the composer. Confirm prompt text and send-button state, then press Enter to continue... ",
        )

        upload_paths = self._coerce_chat_attachment_paths(file_path=file_path, attachment_paths=attachment_paths)
        phase_started = time.monotonic()
        attachment_submit_ready_evidence: dict[str, Any] | None = None
        if upload_paths:
            expected_attachment_filenames = [Path(path).name for path in upload_paths]
            phase_timings["attachment_mode"] = True
            phase_timings["attachment_upload_started"] = True
            phase_timings["attachment_upload_completed"] = False
            phase_timings["attachment_count"] = len(upload_paths)
            phase_timings["attachment_filename_expected"] = expected_attachment_filenames[0] if len(expected_attachment_filenames) == 1 else expected_attachment_filenames
            await self._upload_chat_attachments(page, upload_paths)
            phase_timings["attachment_upload_completed"] = True
            mark_phase("attachment_upload_seconds", phase_started)
            attachment_visibility = await self._capture_attachment_visible_state(page, expected_filenames=expected_attachment_filenames)
            phase_timings["attachment_visibility_status"] = attachment_visibility.get("status")
            phase_timings["attachment_visible"] = attachment_visibility.get("visible")
            phase_timings["attachment_filename_visible"] = attachment_visibility.get("filename_visible")
            phase_timings["attachment_filename_exact_match"] = attachment_visibility.get("exact_filename_match")
            phase_timings["attachment_visibility_evidence"] = attachment_visibility
            attachment_submit_ready_evidence = await self._wait_for_attachment_submit_ready(page)
            phase_timings["attachment_submit_ready_status"] = attachment_submit_ready_evidence.get("status")
            phase_timings["attachment_submit_ready"] = attachment_submit_ready_evidence.get("ready")
            phase_timings["attachment_submit_ready_seconds"] = attachment_submit_ready_evidence.get("duration_seconds")
            phase_timings["attachment_submit_ready_attempt_count"] = attachment_submit_ready_evidence.get("attempt_count")
            phase_timings["attachment_submit_ready_last_state"] = attachment_submit_ready_evidence.get("last_state")
        else:
            phase_timings["attachment_mode"] = False
            phase_timings["attachment_upload_started"] = False
            phase_timings["attachment_upload_completed"] = False
            mark_phase("attachment_upload_seconds", phase_started)

        if file_path:
            self._log("upload", "upload requested", file_path=file_path)
            if not os.path.exists(file_path):
                raise FileNotFoundError(file_path)
            file_input = page.locator('input[type="file"]')
            file_count = await file_input.count()
            self._log("upload", "file input selector count", selector='input[type="file"]', count=file_count)
            if not file_count:
                raise ResponseTimeoutError("File upload input was not found")
            await file_input.first.set_input_files(file_path)
            self._log("upload", "file uploaded to browser input", file_path=file_path)
        mark_phase("attachment_upload_seconds", phase_started)

        phase_started = time.monotonic()
        response_context = await self._capture_response_context(page)
        if isinstance(response_context, dict):
            response_context.update(response_request_binding)
        mark_phase("response_context_seconds", phase_started)
        dom_weight = response_context.get("dom_weight") if isinstance(response_context, dict) else {}
        if isinstance(dom_weight, dict):
            phase_timings["conversation_assistant_turn_count"] = dom_weight.get("assistant_turn_count")
            phase_timings["conversation_user_turn_count"] = dom_weight.get("user_turn_count")
            phase_timings["conversation_generic_turn_count"] = dom_weight.get("generic_turn_count")
            phase_timings["conversation_code_block_count"] = dom_weight.get("code_block_count")
            phase_timings["conversation_code_block_count_mode"] = dom_weight.get("code_block_count_mode")
            phase_timings["large_conversation_dom_detected"] = dom_weight.get("large_conversation_dom_detected")
            phase_timings["recommend_new_task_when_large"] = dom_weight.get("recommend_new_task_when_large")
            phase_timings["dom_weight_capture_seconds"] = dom_weight.get("capture_seconds")
            phase_timings["dom_weight_capture_mode"] = dom_weight.get("capture_mode")
            phase_timings["dom_weight_diagnostic_mode"] = dom_weight.get("diagnostic_mode")
            phase_timings["dom_weight_capture_capped"] = dom_weight.get("capture_capped")
            phase_timings["dom_weight_capture_skipped_reason"] = dom_weight.get("capture_skipped_reason")
            phase_timings["historical_scan_used"] = dom_weight.get("historical_scan_used")
            phase_timings["historical_scan_seconds"] = dom_weight.get("historical_scan_seconds")

        await self._debug_pause_if_enabled(
            label="before_submit",
            enabled=bool(getattr(self.config, "pause_before_submit", False)),
            prompt="Debug pause before submit. Inspect focus, send/stop buttons, and network panel, then press Enter to submit... ",
        )

        if self._page_reports_closed(page):
            return await browser_lifetime_failure_result(submit_phase="pre_submit_closed")

        try:
            submit_evidence = await self._submit_prompt(
                page,
                prompt=prompt,
                prefer_button=bool(prefer_button_submit or upload_paths),
                allow_keyboard_fallback_after_button_prepare_failure=bool(prefer_button_submit and not upload_paths),
            )
        except Exception as exc:
            if self._is_browser_target_closed_error(exc):
                return await browser_lifetime_failure_result(submit_phase="submit_dispatch", exc=exc)
            raise
        if isinstance(submit_evidence, dict):
            # Keep the originating submit policy on the causal evidence object so
            # every downstream JSON envelope can expose it without having to
            # infer it from ask_phase_timings.
            submit_evidence.setdefault("prefer_button_submit", bool(prefer_button_submit))
        # v0.0.278.9 keeps submit timing narrow and reconciliable with
        # service-log timestamps.  submit_wait_seconds now includes the
        # button/Enter dispatch, post-dispatch composer snapshot, and
        # confirmation poll loop; submit_total_seconds remains full
        # _submit_prompt wall clock.
        phase_timings["submit_wait_seconds"] = submit_evidence.get("submit_wait_seconds", submit_evidence.get("duration_seconds"))
        phase_timings["submit_total_seconds"] = submit_evidence.get("duration_seconds")
        phase_timings["composer_state_capture_seconds"] = submit_evidence.get("composer_state_capture_seconds")
        phase_timings["user_turn_state_capture_seconds"] = submit_evidence.get("user_turn_state_capture_seconds")
        phase_timings["assistant_turn_count_seconds"] = submit_evidence.get("assistant_turn_count_seconds")
        phase_timings["send_button_probe_seconds"] = submit_evidence.get("send_button_probe_seconds")
        phase_timings["send_button_wait_seconds"] = submit_evidence.get("send_button_wait_seconds")
        phase_timings["send_button_click_seconds"] = submit_evidence.get("send_button_click_seconds")
        phase_timings["send_button_retry_used"] = submit_evidence.get("send_button_retry_used")
        phase_timings["send_button_retry_reason"] = submit_evidence.get("send_button_retry_reason")
        phase_timings["send_button_retry_seconds"] = submit_evidence.get("send_button_retry_seconds")
        phase_timings["enter_fallback_decision_seconds"] = submit_evidence.get("enter_fallback_decision_seconds")
        phase_timings["submit_to_turn_visible_seconds"] = submit_evidence.get("submit_to_turn_visible_seconds")
        phase_timings["submit_confirmation_seconds"] = submit_evidence.get("submit_confirmation_seconds")
        phase_timings["submit_confirmation_mode"] = submit_evidence.get("submit_confirmation_mode")
        phase_timings["submit_confirmation_fast_path_used"] = submit_evidence.get("submit_confirmation_fast_path_used")
        phase_timings["submit_confirmation_fast_path_reason"] = submit_evidence.get("submit_confirmation_fast_path_reason")
        phase_timings["submit_confirmation_to_running_seconds"] = submit_evidence.get("submit_confirmation_to_running_seconds")
        phase_timings["submit_confirmation_to_new_turn_seconds"] = submit_evidence.get("submit_confirmation_to_new_turn_seconds")
        phase_timings["submit_confirmation_to_url_conversation_seconds"] = submit_evidence.get("submit_confirmation_to_url_conversation_seconds")
        phase_timings["submit_confirmation_probe_seconds"] = submit_evidence.get("submit_confirmation_probe_seconds")
        phase_timings["submit_confirmation_poll_attempt_count"] = submit_evidence.get("submit_confirmation_poll_attempt_count")
        phase_timings["submit_confirmation_historical_count_used"] = submit_evidence.get("submit_confirmation_historical_count_used")
        phase_timings["submit_confirmation_fallback_used"] = submit_evidence.get("submit_confirmation_fallback_used")
        phase_timings["submit_causal_confirmation_required"] = submit_evidence.get("submit_causal_confirmation_required")
        phase_timings["submit_causal_confirmation_verified"] = submit_evidence.get("submit_causal_confirmation_verified")
        phase_timings["submit_causal_confirmation_reason"] = submit_evidence.get("submit_causal_confirmation_reason")
        phase_timings["submit_url_only_confirmation_rejected"] = submit_evidence.get("submit_url_only_confirmation_rejected")
        phase_timings["submit_user_turn_echo_found"] = submit_evidence.get("submit_user_turn_echo_found")
        phase_timings["submit_user_turn_echo_seconds"] = submit_evidence.get("submit_user_turn_echo_seconds")
        phase_timings["submit_backend_task_message_found"] = submit_evidence.get("submit_backend_task_message_found")
        phase_timings["submit_backend_task_message_seconds"] = submit_evidence.get("submit_backend_task_message_seconds")
        phase_timings["submit_backend_task_message_status"] = submit_evidence.get("submit_backend_task_message_status")
        phase_timings["submit_network_request_observed"] = submit_evidence.get("submit_network_request_observed")
        phase_timings["submit_network_request_seconds"] = submit_evidence.get("submit_network_request_seconds")
        phase_timings["submit_network_request_status"] = submit_evidence.get("submit_network_request_status")
        phase_timings["submit_network_request_marker_found"] = submit_evidence.get("submit_network_request_marker_found")
        phase_timings["submit_network_response_observed"] = submit_evidence.get("submit_network_response_observed")
        phase_timings["submit_network_response_status"] = submit_evidence.get("submit_network_response_status")
        phase_timings["submit_network_stream_started"] = submit_evidence.get("submit_network_stream_started")
        phase_timings["submit_network_event_urls"] = submit_evidence.get("submit_network_event_urls")
